window.TADABBUR_YUSUF = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة يوسف (١٢)، سورةٌ مكّيّةٌ هي «أحسنُ القصص»، قصّةُ يوسفَ عليه السلام كاملةً في سياقٍ واحد: الرؤيا، والجُبّ، والعزيز وامرأته، والسجن، والملك، ولقاءُ الإخوة. تُفتتَح بـ«الر». كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":12,"name":"يوسف","total_ayahs":111,"audio":[18,53,64,76,87,90,92,100,101,108],"passages":[{"title":"الكتابُ المبين، وأحسنُ القصص","range":[1,3],"theme":"أنّ القرآنَ عربيٌّ مبين، وأنّ قصّةَ يوسفَ أحسنُ القصصِ يُوحى بها","verses":[{"n":1,"reflection":{"text":"«الر تلك آيات الكتاب المبين»: افتُتحت السورةُ بـ«الر» تنبيهًا على إعجازِ القرآنِ المؤلَّفِ من حروفِهم؛ ثم أشار: تلك الآياتُ العاليةُ آياتُ الكتابِ المبينِ الواضحِ في نفسه المُبيِّنِ لغيره، الذي يفصل الحقَّ من الباطل؛ ففي هذا تعظيمُ القرآنِ ووصفُه بالبيانِ التامّ؛ فعظّم القرآنَ واطلب البيانَ والهدى فيه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["المبين"],"heart_state":{"text":"تعظيمُ القرآنِ وطلبُ البيانِ والهدى فيه."},"action":{"text":"عظّم القرآنَ الكتابَ المبين، واطلب فيه بيانَ الحقّ وهداه، فهو واضحٌ في نفسه مُوضِّحٌ لما تحتاج."}},{"n":2,"reflection":{"text":"«إنا أنزلناه قرآنا عربيا لعلكم تعقلون»: إنا أنزلنا هذا الكتابَ قرآنًا بلسانٍ عربيٍّ مبينٍ لتفهموا معانيه وتعقلوا مواعظه وأحكامه؛ ففي هذا نعمةُ نزولِ القرآنِ بلغةٍ يفهمها المخاطبون لتقوم الحجّةُ ويحصل الانتفاع؛ فاعقل معانيَ القرآنِ وتدبّرها، فقد أُنزل بلسانٍ عربيٍّ مبينٍ لتفقهه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ معاني القرآنِ وإعمالُ العقلِ فيه."},"action":{"text":"اعقل معانيَ القرآنِ وتدبّرها، ولا تقرأه بلا فهم، فقد أُنزل عربيًّا مبينًا لتعقل مواعظه وأحكامه."}},{"n":3,"reflection":{"text":"«نحن نقص عليك أحسن القصص بما أوحينا إليك هذا القرآن وإن كنت من قبله لمن الغافلين»: نحن نقصّ عليك يا محمد أحسنَ القصصِ وأصدقَه وأنفعَه (قصّةَ يوسف) بما أوحينا إليك هذا القرآن، وإن كنت من قبلِ هذا الوحي لمن الغافلين عن هذه الأخبارِ لا تعلمها؛ ففي هذا أنّ علمَ الغيبِ الذي يخبر به النبيُّ برهانُ نبوّته، وأنّ في القصصِ القرآنيِّ أحسنَ العبرِ والعظات؛ فاقرأ قصصَ القرآنِ لتأخذ منها أحسنَ العبرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العبرةِ من قصصِ القرآنِ الصادقةِ النافعة."},"action":{"text":"تدبّر قصصَ القرآنِ فهي أحسنُ القصصِ وأصدقُه، وخذ منها العبرَ والعظاتِ في حياتك، فما قُصّت إلا لتعتبر."}}]},{"title":"رؤيا يوسفَ وتوجيهُ يعقوب","range":[4,6],"theme":"رؤيا النبوّة، وحكمةُ الأبِ في سترها خوفَ الحسد، وبشارةُ الاجتباء","verses":[{"n":4,"reflection":{"text":"«إذ قال يوسف لأبيه يا أبت إني رأيت أحد عشر كوكبا والشمس والقمر رأيتهم لي ساجدين»: اذكر إذ قال يوسفُ لأبيه يعقوبَ: يا أبتِ إني رأيت في المنامِ أحدَ عشرَ كوكبًا والشمسَ والقمرَ رأيتهم لي ساجدين؛ وكانت رؤيا نبوّةٍ صادقةٍ (الكواكبُ إخوتُه، والشمسُ والقمرُ أبواه)؛ ففي هذا أنّ الرؤيا الصالحةَ من مبشّراتِ الله، وأنّ الله يهيّئ لأوليائه أسبابَ الرفعة؛ فأبشر بأنّ الله يدبّر لأوليائه الخيرَ من حيث لا يحتسبون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى أنّ الله يدبّر لأوليائه الخيرَ ويهيّئ أسبابه."},"action":{"text":"ثق بأنّ الله يدبّر لك الخيرَ ويهيّئ أسبابَ الرفعةِ من حيث لا تدري، كما بشّر يوسفَ بالرؤيا قبل تحقّقها."}},{"n":5,"reflection":{"text":"«قال يا بني لا تقصص رؤياك على إخوتك فيكيدوا لك كيدا إن الشيطان للإنسان عدو مبين»: قال يعقوبُ لابنه: يا بنيَّ لا تحدّث بهذه الرؤيا إخوتك فيحسدوك ويدبّروا لك مكرًا وأذًى، إنّ الشيطانَ للإنسانِ عدوٌّ بيّنُ العداوةِ يسعى بالإفسادِ بين الإخوة؛ ففي هذا حكمةُ سترِ النعمةِ خوفَ الحسد، والتحذيرُ من كيدِ الشيطان؛ فاستر نعمتك عمّن تخشى حسده، واحذر نزغَ الشيطانِ بين ذوي القربى.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الشيطان عدو مبين"],"heart_state":{"text":"سترُ النعمةِ خوفَ الحسد، والحذرُ من كيدِ الشيطان."},"action":{"text":"استر نعمتك عمّن قد يحسدك، ولا تُحدّث بكلِّ ما يسرّك، واحذر أن يفسد الشيطانُ ما بينك وبين قرابتك."}},{"n":6,"reflection":{"text":"«وكذلك يجتبيك ربك ويعلمك من تأويل الأحاديث ويتم نعمته عليك وعلى آل يعقوب كما أتمها على أبويك من قبل إبراهيم وإسحاق إن ربك عليم حكيم»، وكما أراك الله تلك الرؤيا كذلك يصطفيك ربّك للنبوّةِ والرفعة، ويعلّمك تعبيرَ الرؤى وتفسيرَ الكلام، ويتمّ نعمتَه عليك بالنبوّةِ والملكِ وعلى آلِ يعقوبَ كما أتمّها على جدّيك إبراهيمَ وإسحاقَ من قبل، إنّ ربّك عليمٌ بمن يستحقّ الاصطفاءَ حكيمٌ في تدبيره؛ ففي هذا أنّ اصطفاءَ الله وإتمامَ نعمته بعلمِه وحكمته؛ فاطلب فضلَ الله واجتباءه بالطاعة، واثق بحكمته في تدبيرِ أمرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العليم","الحكيم"],"heart_state":{"text":"طلبُ فضلِ الله واجتبائه، والثقةُ بحكمتِه في التدبير."},"action":{"text":"اطلب فضلَ الله واصطفاءه بالطاعةِ والإخلاص، وثق بأنّ ربّك عليمٌ حكيمٌ يتمّ نعمته على من اجتباه."}}]},{"title":"حسدُ الإخوةِ وائتمارُهم بيوسف","range":[7,10],"theme":"أنّ في القصّةِ آياتٍ للمعتبرين، وأنّ الحسدَ يقود إلى أعظمِ الجرائم","verses":[{"n":7,"reflection":{"text":"«لقد كان في يوسف وإخوته آيات للسائلين»: لقد كان في قصّةِ يوسفَ وإخوته عبرٌ وعظاتٌ ودلائلُ على قدرةِ الله وحكمته لمن يسأل عنها ويطلب الاعتبار؛ ففي هذا أنّ القصّةَ مملوءةٌ بالآياتِ لمن تدبّرها؛ فاطلب العبرةَ من قصّةِ يوسفَ فهي آياتٌ لمن سأل واعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العبرِ والآياتِ من قصّةِ يوسفَ بالتدبّرِ والسؤال."},"action":{"text":"تدبّر قصّةَ يوسفَ وإخوته باحثًا عن العبرِ والآيات، فهي مملوءةٌ بالدلائلِ لمن سأل واعتبر."}},{"n":8,"reflection":{"text":"«إذ قالوا ليوسف وأخوه أحب إلى أبينا منا ونحن عصبة إن أبانا لفي ضلال مبين»: إذ قال إخوةُ يوسف: ليوسفُ وأخوه (بنيامين) أحبُّ إلى أبينا منا مع أننا جماعةٌ أقوياءُ ننفعه، إنّ أبانا لفي خطأٍ بيّنٍ في تفضيلهما علينا؛ ففي هذا أنّ الحسدَ يعمي عن الحقِّ حتى يُخطّئوا أباهم النبيّ؛ فاحذر الحسدَ فإنه يقلب الموازينَ ويعمي البصيرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الحسدِ الذي يعمي عن الحقِّ ويقلب الموازين."},"action":{"text":"احذر الحسدَ فإنه يعمي عن الحقّ حتى يخطّئ صاحبُه الصوابَ ويقلب الموازين، وطهّر قلبك من الغلِّ على إخوانك."}},{"n":9,"reflection":{"text":"«اقتلوا يوسف أو اطرحوه أرضا يخل لكم وجه أبيكم وتكونوا من بعده قوما صالحين»: قال بعضُهم: اقتلوا يوسفَ أو أبعدوه إلى أرضٍ بعيدةٍ يتفرّغ لكم حبُّ أبيكم وإقبالُه عليكم، وتوبوا من بعدِ ذنبكم فتكونوا قومًا صالحين؛ ففي هذا أنّ الحسدَ قاد إلى تدبيرِ القتل، وأنهم أرادوا المعصيةَ ثم التوبةَ (تسويفٌ خطير)؛ فاحذر أن يجرّك الحسدُ إلى الجريمة، ولا تعزم على معصيةٍ متّكلًا على توبةٍ بعدها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يجرّ الحسدُ إلى الجريمة، ومن تسويفِ التوبة."},"action":{"text":"لا تدع الحسدَ يجرّك إلى ظلمِ أحد، ولا تعزم على ذنبٍ ناويًا التوبةَ بعده، فذاك تسويفٌ ومكرٌ بالنفس."}},{"n":10,"reflection":{"text":"«قال قائل منهم لا تقتلوا يوسف وألقوه في غيابت الجب يلتقطه بعض السيارة إن كنتم فاعلين»: قال قائلٌ منهم (أرحمُهم، وهو يهوذا أو الأكبر): لا تقتلوا يوسفَ فالقتلُ عظيم، بل ألقوه في قعرِ البئرِ المظلمِ يلتقطه بعضُ المسافرين فيبعدونه، إن كنتم عازمين على فعلِ شيءٍ به؛ ففي هذا أنّ في القومِ من يخفّف الشرَّ ويكفّ عن أعظمه؛ فادفع أعظمَ الشرّين بأخفّهما إن لم تقدر على دفعهما، وكن أرفقَ القومِ بالحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تخفيفُ الشرِّ ودفعُ أعظمِ الضررين إذا لم يُدفعا معًا."},"action":{"text":"إذا لم تقدر على منعِ الشرِّ كلِّه فاسعَ في تخفيفه ودفعِ أعظمه، وكن ممّن يكفّ عن الجريمةِ لا ممّن يزيّنها."}}]},{"title":"خداعُ الأبِ لأخذِ يوسف","range":[11,14],"theme":"استئذانُ الإخوةِ بالخداع، وحذرُ يعقوبَ وتوجّسُه","verses":[{"n":11,"reflection":{"text":"«قالوا يا أبانا ما لك لا تأمنا على يوسف وإنا له لناصحون»: قال الإخوةُ لأبيهم: يا أبانا ما بالك لا تأمنّا على يوسفَ وتخشى علينا منه، وإنا له لمحبّون ناصحون نريد له الخير؟ فأظهروا النصحَ وأبطنوا الكيد؛ ففي هذا أنّ أهلَ السوءِ قد يتظاهرون بالنصحِ لبلوغِ مقاصدهم؛ فاحذر من يُظهر لك النصحَ ويبطن الكيد، ولا تُخدَع بحسنِ القول.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ ممّن يُظهر النصحَ ويبطن الكيد، وعدمُ الاغترارِ بالقول."},"action":{"text":"لا تغترّ بمن يُظهر لك النصحَ والمحبّة وقد يبطن غيرها، وتثبّت في الأمورِ ولا تُخدَع بحسنِ المقال."}},{"n":12,"reflection":{"text":"«أرسله معنا غدا يرتع ويلعب وإنا له لحافظون»: أرسل يوسفَ معنا غدًا إلى المرعى يأكل من ثمارِه ويلعب وينشرح، وإنا له لحافظون من كلِّ سوء؛ فأغروه بما يظنّون أنه يحبّه للصبيِّ من اللعبِ والانبساط؛ ففي هذا استعمالُهم الوسائلَ المزيّنةَ لبلوغِ مرادهم؛ فتيقّظ للوسائلِ المزيّنةِ التي يُتوصّل بها إلى الشرّ، ولا تُلقِ من تحبّ في مواطنِ الريبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التيقّظُ للوسائلِ المزيّنةِ التي يُتوصّل بها إلى الشرّ."},"action":{"text":"تيقّظ للإغراءاتِ المزيّنةِ التي قد يُتوصّل بها إلى ضررٍ، ولا تسلّم من تحبّ لمن لا تطمئنّ إليه."}},{"n":13,"reflection":{"text":"«قال إني ليحزنني أن تذهبوا به وأخاف أن يأكله الذئب وأنتم عنه غافلون»: قال يعقوبُ: إنه يحزنني فراقُه ومفارقتُه ولو ساعة، وأخاف أن يأكله الذئبُ وأنتم مشغولون عنه غافلون؛ ففي هذا شفقةُ الأبِ وتوجّسُه (وقد لقّنهم من حيث لا يشعر حجّةَ الذئب)؛ ففي هذا أنّ الحبَّ يورث الشفقةَ والحذر؛ فكن حذرًا على من تحبّ، ولا تغفل عن أمانةٍ استُرعيتها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشفقةُ على الأحبّةِ والحذرُ عليهم من مواطنِ الخطر."},"action":{"text":"كن حذرًا شفيقًا على من تحبّ وتُؤتمن عليه، ولا تغفل عن الأمانةِ التي استُرعيتها، فالغفلةُ بابُ الضياع."}},{"n":14,"reflection":{"text":"«قالوا لئن أكله الذئب ونحن عصبة إنا إذا لخاسرون»: قال الإخوةُ: لئن أكله الذئبُ ونحن جماعةٌ أقوياءُ نحفظه، إنا إذًا لعاجزون هالكون لا خيرَ فينا؛ فأكّدوا حفظهم له بالحلفِ الضمنيّ ليطمئن أبوهم؛ ففي هذا أنّ أهلَ الكيدِ يبالغون في تأكيدِ الأمانةِ ليخفوا خيانتهم؛ فلا تطمئن لكثرةِ التوكيدِ من مريبٍ، فالمبالغةُ في التأكيدِ قد تخفي الخيانة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاطمئنانِ لكثرةِ التوكيدِ ممّن يُخشى منه."},"action":{"text":"لا تطمئن لمجرّدِ كثرةِ الحلفِ والتأكيدِ من مريب، فالمبالغةُ في التوكيدِ قد تُخفي وراءها خيانةً وكيدًا."}}]},{"title":"إلقاءُ يوسفَ في الجبِّ والوحيُ إليه","range":[15,15],"theme":"تنفيذُ الكيد، ولطفُ الله بيوسفَ بالوحيِ والتبشير","verses":[{"n":15,"reflection":{"text":"«فلما ذهبوا به وأجمعوا أن يجعلوه في غيابت الجب وأوحينا إليه لتنبئنهم بأمرهم هذا وهم لا يشعرون»: فلما ذهبوا بيوسفَ وعزموا جميعًا على إلقائه في قعرِ البئر، ونفّذوا كيدهم، أوحينا إلى يوسفَ (تثبيتًا وتبشيرًا): لتخبرنّهم يومًا بفعلتهم هذه وأنت في عزٍّ وتمكين وهم لا يعرفونك ولا يشعرون؛ ففي هذا لطفُ الله بعبده في شدّته، وبشارتُه بالفرجِ وهو في قاعِ البئر؛ ففي أشدِّ الكربِ يأتي لطفُ الله وبشارتُه؛ فاطمئن إلى أنّ مع العسرِ يسرًا، وأنّ الله لا يترك أولياءه في الشدّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى لطفِ الله وبشارتِه في أشدِّ الكرب."},"action":{"text":"إذا اشتدّ بك الكربُ فاطمئن إلى لطفِ الله وقربِ فرجه، فقد بشّر يوسفَ بالنجاةِ والعزّ وهو في قاعِ الجبّ."}}]},{"title":"كذبةُ الإخوة، وصبرُ يعقوبَ الجميل","range":[16,18],"theme":"افتضاحُ الكذبِ بالقرائن، وجمالُ الصبرِ والاستعانةِ بالله","verses":[{"n":16,"reflection":{"text":"«وجاءوا أباهم عشاء يبكون»، وجاء الإخوةُ أباهم يعقوبَ وقتَ العشاءِ (في الظلامِ ليخفوا انفعالهم) وهم يتظاهرون بالبكاءِ والحزنِ على يوسف؛ ففي هذا أنّ البكاءَ قد يكون مصطنعًا لتغطيةِ الكذب، وأنّ أهلَ الباطلِ يتقنون التمثيل؛ فلا تُخدَع بالدموعِ والمظاهر، فالبكاءُ قد يُصطنَع لسترِ الخيانة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالمظاهرِ والدموعِ المصطنعة."},"action":{"text":"لا تحكم على الناسِ بمظاهرهم ودموعهم، فقد تُصطنَع لسترِ الباطل، بل تثبّت وتحرَّ الحقيقةَ بالقرائن."}},{"n":17,"reflection":{"text":"«قالوا يا أبانا إنا ذهبنا نستبق وتركنا يوسف عند متاعنا فأكله الذئب وما أنت بمؤمن لنا ولو كنا صادقين»: قالوا: يا أبانا ذهبنا نتسابق ونترامى وتركنا يوسفَ عند أمتعتنا فأكله الذئبُ، وما أنت بمصدّقٍ لنا ولو كنّا صادقين (لسوءِ ظنّك بنا)؛ فقدّموا العذرَ واستبقوا اتّهامَ أنفسهم بالكذب؛ ففي هذا أنّ الكاذبَ يستبق الدفعَ عن نفسه بما يفضحه؛ فتثبّت في الأخبار، فقد يفضح الكاذبَ حرصُه على تبرئةِ نفسه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التثبّتُ في الأخبار، فحرصُ الكاذبِ على تبرئةِ نفسه يفضحه."},"action":{"text":"تثبّت في الأخبارِ ولا تتعجّل التصديق، فالكاذبُ كثيرًا ما يفضحه حرصُه على استباقِ التبرئةِ والدفعِ عن نفسه."}},{"n":18,"reflection":{"text":"«وجاءوا على قميصه بدم كذب قال بل سولت لكم أنفسكم أمرا فصبر جميل والله المستعان على ما تصفون»، وجاءوا على قميصِ يوسفَ بدمٍ كذبٍ (دمِ شاةٍ، ونسوا أن يمزّقوا القميص فافتُضحوا)، قال يعقوب: بل زيّنت لكم أنفسكم أمرًا فعلتموه، فصبري صبرٌ جميلٌ لا شكوى فيه لغيرِ الله، والله المستعانُ على ما تصفون من الكذب؛ ففي هذا أنّ الكذبَ تفضحه القرائن، وأنّ الصبرَ الجميلَ والاستعانةَ بالله سلاحُ المؤمنِ في المصيبة؛ فإذا نزلت بك مصيبةٌ فاصبر صبرًا جميلًا واستعن بالله وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["صبر جميل","المستعان"],"heart_state":{"text":"الصبرُ الجميلُ عند المصيبةِ والاستعانةُ بالله وحده."},"action":{"text":"إذا نزلت بك مصيبةٌ فاصبر صبرًا جميلًا لا جزعَ فيه ولا شكوى لغيرِ الله، واستعن بالله وحده على ما يصفه الظالمون."}}]},{"title":"التقاطُ السيارةِ ليوسف، وبيعُه بثمنٍ بخس","range":[19,20],"theme":"تدبيرُ الله لخروجِ يوسفَ من الجبّ، وهوانُ ما زهد فيه الناسُ عند الله","verses":[{"n":19,"reflection":{"text":"«وجاءت سيارة فأرسلوا واردهم فأدلى دلوه قال يا بشرى هذا غلام وأسروه بضاعة والله عليم بما يعملون»، وجاءت قافلةٌ مسافرةٌ فأرسلوا من يستقي لهم الماء، فأدلى دلوَه في البئرِ فتعلّق بها يوسف، فقال مستبشرًا: يا بشرى هذا غلامٌ نفيس! وأخفوه ليبيعوه كبضاعةٍ من التجارة، والله عليمٌ بما يعملون به لا يخفى عليه شيء؛ ففي هذا أنّ الله يدبّر أسبابَ النجاةِ من حيث لا يُحتسب؛ فاطمئن إلى أنّ الله يهيّئ لك المخرجَ في وقته، فمن كان في قاعِ البئرِ رفعه الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العليم"],"heart_state":{"text":"الثقةُ بأنّ الله يهيّئ أسبابَ الفرجِ من حيث لا يُحتسب."},"action":{"text":"ثق بأنّ الله يدبّر لك المخرجَ من الشدّةِ في وقته ومن حيث لا تدري، كما هيّأ للقافلةِ أن تُخرج يوسفَ من الجبّ."}},{"n":20,"reflection":{"text":"«وشروه بثمن بخس دراهم معدودة وكانوا فيه من الزاهدين»، وباعه إخوتُه (أو الملتقطون) بثمنٍ زهيدٍ ناقصٍ دراهمَ قليلةٍ معدودة، وكانوا فيه من الزاهدين الراغبين عنه لا يبالون به؛ ففي هذا أنّ ما زهد فيه الناسُ قد يكون أعظمَ قدرًا عند الله، وأنّ العبرةَ بمنزلةِ المرءِ عند الله لا عند الخلق؛ فلا تقس قيمةَ نفسك بنظرةِ الناسِ إليك، فربّ مزهودٍ فيه رفعه الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا تُقاسَ القيمةُ بنظرةِ الناس، فربّ مزهودٍ رفعه الله."},"action":{"text":"لا تقس قيمتك بما يراه الناسُ فيك، فربّ من زهد الناسُ فيه رفعه الله وأعلى قدره، فالعبرةُ بمنزلتك عند الله."}}]},{"title":"إكرامُ العزيزِ ليوسف، وتمكينُ الله له","range":[21,22],"theme":"لطفُ الله في تهيئةِ أسبابِ التمكين، وأنّ الله غالبٌ على أمره","verses":[{"n":21,"reflection":{"text":"«وقال الذي اشتراه من مصر لامرأته أكرمي مثواه عسى أن ينفعنا أو نتخذه ولدا وكذلك مكنا ليوسف في الأرض ولنعلمه من تأويل الأحاديث والله غالب على أمره ولكن أكثر الناس لا يعلمون»، وقال عزيزُ مصرَ الذي اشتراه لامرأته: أحسني منزلته ومقامه عندنا، عسى أن ينفعنا بخدمته أو نتّخذه ولدًا (لما رأى فيه من مخايلِ النجابة)؛ وكذلك مكّنّا ليوسفَ في أرضِ مصرَ (بدخوله بيتَ العزيز) لنهيّئه للملكِ ولنعلّمه تعبيرَ الرؤى، والله غالبٌ على أمره لا يُغلَب، ينفّذ ما يريد، ولكنّ أكثرَ الناسِ لا يعلمون حكمةَ تدبيره؛ ففي هذا أنّ الله يسوق أسبابَ التمكينِ لأوليائه في طيّ المحن؛ فاطمئن إلى أنّ الله غالبٌ على أمره، يدبّر لك الخيرَ من خلالِ ما تكرهه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["غالب على أمره"],"heart_state":{"text":"الثقةُ بأنّ الله غالبٌ على أمره، يسوق التمكينَ في طيِّ المحن."},"action":{"text":"ثق بأنّ الله غالبٌ على أمره يدبّر لك الخيرَ حتى من خلالِ ما تكرهه، فما دخل يوسفُ مصرَ عبدًا إلا لِيُمكَّن فيها ملكًا."}},{"n":22,"reflection":{"text":"«ولما بلغ أشده آتيناه حكما وعلما وكذلك نجزي المحسنين»، ولما بلغ يوسفُ كمالَ قوّته ورشدَه، آتيناه حكمةً وفقهًا في الدينِ وعلمًا نافعًا، ومثلَ ذلك الجزاءِ نجزي المحسنين في أعمالهم وأقوالهم؛ ففي هذا أنّ الإحسانَ سببٌ للعلمِ والحكمةِ والتمكين؛ فأحسن في عملك وطاعتك يؤتك الله علمًا وحكمةً، فالجزاءُ من جنسِ العمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يجزي المحسنين"],"heart_state":{"text":"أنّ الإحسانَ سببٌ لنيلِ العلمِ والحكمةِ من الله."},"action":{"text":"أحسن في عبادتك ومعاملتك وعملك، فالله يجزي المحسنين علمًا وحكمةً وتمكينًا، والجزاءُ من جنسِ العمل."}}]},{"title":"المراودةُ والعصمةُ ببرهانِ الله","range":[23,24],"theme":"عفّةُ يوسفَ ومعاذُ الله من الفاحشة، وأنّ برهانَ الله يعصم المخلَصين","verses":[{"n":23,"reflection":{"text":"«وراودته التي هو في بيتها عن نفسه وغلقت الأبواب وقالت هيت لك قال معاذ الله إنه ربي أحسن مثواي إنه لا يفلح الظالمون»، وطلبت منه امرأةُ العزيزِ الفاحشةَ وأرادته على نفسه، وأغلقت الأبوابَ وتهيّأت وقالت: هلمّ إليّ وأقبل؛ فقال يوسفُ ممتنعًا: أعوذ بالله وأعتصم به من هذا، إنّ سيّدي (العزيز) أحسن منزلتي فكيف أخونه في أهله؟ إنه لا يفلح الظالمون الذين يقابلون الإحسانَ بالخيانةِ ويقعون في الحرام؛ ففي هذا أنّ الاستعاذةَ بالله والتذكّرَ للحقوقِ عصمةٌ من الفاحشة؛ فإذا دُعيت إلى معصيةٍ فاستعذ بالله واذكر حقَّ الله وحقَّ من أحسن إليك، فذاك عصمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["معاذ الله"],"heart_state":{"text":"العفّةُ بالاستعاذةِ بالله وتذكّرِ الحقوقِ عند الفتنة."},"action":{"text":"إذا دُعيت إلى فاحشةٍ فقل «معاذ الله»، واستعذ به واذكر حقَّه وحقَّ من أحسن إليك، فتلك عصمةٌ من الوقوعِ في الحرام."}},{"n":24,"reflection":{"text":"«ولقد همت به وهم بها لولا أن رأى برهان ربه كذلك لنصرف عنه السوء والفحشاء إنه من عبادنا المخلصين»، ولقد قصدته المرأةُ قصدًا جازمًا بالفاحشة، وهمّ بها يوسفُ بمقتضى الجِبِلّةِ البشريّةِ (خاطرٌ لم يُتبَع)، لكنه لمّا رأى برهانَ ربّه (حجّةَ الإيمانِ وخشيةَ الله) انصرف عنها وثبت؛ كذلك ثبّتناه لنبعد عنه السوءَ والفاحشة، إنه من عبادنا المُخلَصين الذين أخلصهم الله لطاعته؛ ففي هذا أنّ العصمةَ من الفاحشةِ ببرهانِ الإيمانِ وخشيته، وأنّ الله يحفظ المخلَصين؛ فاستحضر برهانَ الإيمانِ وخشيةَ الله عند الفتنة، يصرف الله عنك السوءَ والفحشاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":["عبادنا المخلصين"],"heart_state":{"text":"أنّ خشيةَ الله وبرهانَ الإيمانِ يصرفان عن الفاحشة."},"action":{"text":"استحضر خشيةَ الله وبرهانَ الإيمانِ عند هجومِ الفتنة، فبه يصرف الله عنك السوءَ والفحشاء كما صرفه عن يوسف."}}]},{"title":"شهادةُ القميص، وبراءةُ يوسف","range":[25,29],"theme":"ظهورُ الحقِّ بالقرائن، وكيدُ النساء، وأمرُ العزيزِ بكتمِ الأمر","verses":[{"n":25,"reflection":{"text":"«واستبقا الباب وقدت قميصه من دبر وألفيا سيدها لدى الباب قالت ما جزاء من أراد بأهلك سوءا إلا أن يسجن أو عذاب أليم»، وتسابقا إلى البابِ (هو هاربٌ وهي تطلبه)، فأمسكت قميصَه من خلفٍ فشقّته، ووجدا زوجها عند الباب؛ فبادرت المرأةُ إلى قلبِ الحقيقةِ واتّهامِه لتبرّئ نفسها: ما عقوبةُ من أراد بأهلك فاحشةً إلا السجنُ أو العذابُ الأليم؟ ففي هذا أنّ أهلَ الباطلِ يقلبون الحقائقَ ويتّهمون البريءَ ليبرّئوا أنفسهم؛ فلا تتّهم بريئًا لتبرّئ نفسك، فذاك ظلمٌ مضاعف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قلبِ الحقائقِ واتّهامِ البريءِ لتبرئةِ النفس."},"action":{"text":"لا تتّهم بريئًا لتدفع التهمةَ عن نفسك، فقلبُ الحقائقِ وظلمُ البريءِ من أقبحِ الظلمِ وأخبثِ الكيد."}},{"n":26,"reflection":{"text":"«قال هي راودتني عن نفسي وشهد شاهد من أهلها إن كان قميصه قد من قبل فصدقت وهو من الكاذبين»: قال يوسفُ صادقًا: هي التي طلبتني وراودتني عن نفسي، فبرّأ نفسه بالصدق؛ وشهد شاهدٌ من أهلها (رجلٌ حكيمٌ) بالقرينة: إن كان قميصُه شُقّ من الأمامِ فصدقت المرأةُ وهو من الكاذبين (لأنه يكون قد أقبل عليها فدفعته)؛ ففي هذا أنّ القرائنَ تكشف الحقّ، وأنّ الحقَّ يُنصَر بالحجّةِ العادلة؛ فتحرَّ الحقَّ بالقرائنِ والأدلّة، ولا تحكم بالهوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الحقِّ بالقرائنِ والأدلّةِ العادلةِ لا بالهوى."},"action":{"text":"تحرَّ الحقَّ في الخصوماتِ بالقرائنِ والأدلّةِ العادلة، ولا تحكم بالهوى أو الظنّ، فالقرينةُ تكشف الصادقَ من الكاذب."}},{"n":27,"reflection":{"text":"«وإن كان قميصه قد من دبر فكذبت وهو من الصادقين»، وإن كان قميصُه شُقّ من الخلفِ فكذبت المرأةُ وهو من الصادقين (لأنه يكون قد أدبر هاربًا فجذبته من خلفه)؛ ففي هذا تكملةُ ميزانِ القرينةِ العادلةِ التي تُظهر الحقّ؛ فاعدل في الحكمِ واتّبع الدليل، فالعدلُ يُظهر الصادقَ من الكاذب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العدلُ في الحكمِ واتّباعُ الدليلِ الكاشفِ للحقّ."},"action":{"text":"اعدل في حكمك واتّبع الدليلَ والقرينةَ الكاشفة، فبالعدلِ والتحرّي يظهر الصادقُ من الكاذبِ وينتصف المظلوم."}},{"n":28,"reflection":{"text":"«فلما رأى قميصه قد من دبر قال إنه من كيدكن إن كيدكن عظيم»: فلما رأى العزيزُ قميصَ يوسفَ شُقّ من الخلف، علم براءةَ يوسفَ وصدقَه، وقال لامرأته: إنّ هذا الاتّهامَ من كيدكنّ أيتها النساء، إنّ كيدكنّ عظيمٌ إذا وقع؛ ففي هذا أنّ الحقَّ ظهر بالقرينة، وأنّ كيدَ النفسِ الأمّارةِ عظيمٌ يُحذَر؛ فاحذر مواطنَ الفتنةِ وكيدَها، وافرح إذ يُظهر الله الحقَّ ويبرّئ البريء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الفرحُ بظهورِ الحقِّ وبراءةِ البريء، والحذرُ من مكامنِ الفتنة."},"action":{"text":"احذر مواطنَ الفتنةِ ومكايدها، واطمئن إلى أنّ الله يُظهر الحقَّ ويبرّئ البريءَ ولو بعد اتّهام، فالحقُّ لا يُدفن."}},{"n":29,"reflection":{"text":"«يوسف أعرض عن هذا واستغفري لذنبك إنك كنت من الخاطئين»: قال العزيزُ ليوسف: أعرض عن ذكرِ هذا الأمرِ واكتمه، وقال لامرأته: استغفري لذنبك، إنك كنت من المخطئين الآثمين؛ ففي هذا معالجةُ العزيزِ للأمرِ بسترٍ وكتمٍ لكنه ضعيفٌ في إنكارِ المنكر (اكتفى بالأمرِ بالاستغفار)؛ ففي هذا أنّ سترَ العوراتِ محمود، لكن لا بدّ من الإنكارِ الجادِّ للمنكر؛ فاستر ما ينبغي ستره، وأنكر المنكرَ إنكارًا جادًّا لا تهاونَ فيه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سترُ ما يُستر مع الإنكارِ الجادِّ للمنكرِ لا التهاونِ فيه."},"action":{"text":"استر ما يليق سترُه من العورات، لكن لا تتهاون في إنكارِ المنكرِ ومعالجته بجدّية، فالسترُ لا يعني إقرارَ الباطل."}}]},{"title":"مكرُ النسوةِ، وحفلةُ التقطيع","range":[30,32],"theme":"انتشارُ الفتنة، وإظهارُ المرأةِ عذرها بجمالِ يوسف، وتهديدُها له","verses":[{"n":30,"reflection":{"text":"«وقال نسوة في المدينة امرأت العزيز تراود فتاها عن نفسه قد شغفها حبا إنا لنراها في ضلال مبين»، وتحدّث نسوةٌ في المدينةِ منكراتٍ على امرأةِ العزيز: امرأةُ العزيزِ تطلب خادمها الفاحشة، قد بلغ حبُّه شِغافَ قلبها، إنا لنراها في خطأٍ بيّنٍ إذ تعشق عبدها؛ ففي هذا انتشارُ الأخبارِ والعيبِ في الناس؛ فاحذر الوقوعَ في الفتنةِ فيشيع أمرك ويعيبك الناس، وصن نفسك عن مواطنِ الريبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"صونُ النفسِ عن مواطنِ الريبةِ التي يشيع بها العيب."},"action":{"text":"صن نفسك عن كلِّ ما يوقعك في الفتنةِ أو الريبة، فالمعصيةُ يشيع أمرُها ويعيب صاحبها، واحفظ عرضك ودينك."}},{"n":31,"reflection":{"text":"«فلما سمعت بمكرهن أرسلت إليهن وأعتدت لهن متكأ وآتت كل واحدة منهن سكينا وقالت اخرج عليهن فلما رأينه أكبرنه وقطعن أيديهن وقلن حاش لله ما هذا بشرا إن هذا إلا ملك كريم»: فلما سمعت امرأةُ العزيزِ بلومهنّ وعيبهنّ (مكرهنّ) دبّرت لتُظهر لهنّ عذرها: أرسلت إليهنّ ودعتهنّ إلى مجلسٍ وهيّأت لكلٍّ سكّينًا وطعامًا، ثم أمرت يوسفَ أن يخرج عليهنّ، فلما رأينه أعظمنه وبُهرن بجماله فجرحن أيديهنّ بالسكاكينِ من الذهول، وقلن: تنزيهًا لله ما هذا بشرًا، ما هذا إلا ملَكٌ كريم؛ ففي هذا أنّ الجمالَ فتنةٌ تُذهل، وأنّ الله جعل جمالَ يوسفَ عذرًا ظاهرًا؛ فاحذر فتنةَ الجمالِ والنظر، فمن أُعطي جمالًا فليحفظه في طاعةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من فتنةِ النظرِ والجمال، وحفظُ ما أُعطيه المرءُ في الطاعة."},"action":{"text":"احذر فتنةَ النظرِ والانبهارِ بالجمال، ومن رزقه الله جمالًا أو نعمةً فليحفظها في طاعتِه لا في معصيته."}},{"n":32,"reflection":{"text":"«قالت فذلكن الذي لمتنني فيه ولقد راودته عن نفسه فاستعصم ولئن لم يفعل ما آمره ليسجنن وليكونا من الصاغرين»: قالت امرأةُ العزيزِ لهنّ بعد أن رأينه: فهذا هو الذي لمتنّني في حبّه، ولقد طلبته عن نفسه فامتنع وعصم نفسه، ولئن لم يفعل ما آمره به ليُسجننّ وليكوننّ من الأذلّاء الصاغرين! فأعلنت عزمها على الظلمِ إن لم يطعها؛ ففي هذا أنّ صاحبَ الهوى قد يجاهر بالباطلِ ويتوعّد على الحقّ؛ فاثبت على العفّةِ ولو هُدّدت، ولا يزحزحك عن الحقِّ وعيدُ أهلِ الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على العفّةِ والحقِّ ولو تُوُعّد بالأذى والسجن."},"action":{"text":"اثبت على عفّتك وطاعةِ الله ولو هُدّدت بالأذى أو السجن، فلا يزحزحك عن الحقِّ وعيدُ أهلِ الهوى."}}]},{"title":"دعاءُ يوسفَ: السجنُ أحبُّ إليّ، واستجابةُ الله","range":[33,34],"theme":"إيثارُ السجنِ على المعصية، والالتجاءُ إلى الله لصرفِ الكيد","verses":[{"n":33,"reflection":{"text":"«قال رب السجن أحب إلي مما يدعونني إليه وإلا تصرف عني كيدهن أصب إليهن وأكن من الجاهلين»: قال يوسفُ ملتجئًا إلى ربّه: ربِّ السجنُ الذي هدّدنني به أحبُّ إليّ من الفاحشةِ التي يدعونني إليها، وإن لم تصرف عني كيدهنّ ومكرهنّ أمِل إليهنّ بمقتضى البشريّةِ وأكن من الجاهلين العاصين؛ ففي هذا إيثارُ يوسفَ البلاءَ على المعصية، واعترافُه بضعفِ النفسِ وافتقاره إلى عصمةِ الله؛ فآثر أشدَّ البلاءِ على المعصية، والتجئ إلى الله أن يعصمك، فلا حولَ لك إلا به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السجن أحب إلي"],"heart_state":{"text":"إيثارُ البلاءِ على المعصية، والافتقارُ إلى عصمةِ الله."},"action":{"text":"آثر البلاءَ والمشقّةَ على معصيةِ الله، والتجئ إليه أن يصرف عنك الفتنة، فلا عصمةَ لك إلا بحفظه وتوفيقه."}},{"n":34,"reflection":{"text":"«فاستجاب له ربه فصرف عنه كيدهن إنه هو السميع العليم»: فاستجاب الله دعاءَ يوسفَ فصرف عنه كيدَ النسوةِ ومكرهنّ وثبّته على العفّة، إنه هو السميعُ لدعاءِ الداعين العليمُ بأحوالهم وحاجاتهم؛ ففي هذا أنّ الله يستجيب لمن التجأ إليه ويصرف عنه الفتنة؛ فالتجئ إلى الله السميعِ العليمِ عند الفتنة، فهو يسمع دعاءك ويعصمك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"الالتجاءُ إلى الله السميعِ العليمِ عند الفتنة، والثقةُ بإجابته."},"action":{"text":"ادعُ الله عند الفتنِ أن يصرفها عنك، وثق بأنه السميعُ العليمُ يستجيب لمن التجأ إليه ويعصمه، كما عصم يوسف."}}]},{"title":"دخولُ السجن، ورؤيا الفتيين، ودعوةُ يوسف","range":[35,38],"theme":"صبرُ يوسفَ في السجن، واغتنامُه الفرصةَ للدعوةِ إلى التوحيد","verses":[{"n":35,"reflection":{"text":"«ثم بدا لهم من بعد ما رأوا الآيات ليسجننه حتى حين»: ثم ظهر للعزيزِ وأهله من بعدِ ما رأوا الأدلّةَ على براءةِ يوسفَ أن يسجنوه إلى مدّةٍ لتنقطع الألسنةُ عن ذكرِ المرأة؛ فسُجن بريئًا لمصلحةٍ لهم؛ ففي هذا أنّ المؤمنَ قد يُبتلى بالظلمِ رغم براءته، وأنّ الله يجعل من المحنةِ منحة؛ فاصبر إذا ابتُليت بظلمٍ لا ذنبَ لك فيه، فمن وراءِ المحنةِ حكمةٌ ومنحة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الظلمِ والابتلاءِ رغمَ البراءة، وحسنُ الظنِّ بالله."},"action":{"text":"اصبر إذا ابتُليت بظلمٍ لا ذنبَ لك فيه، وأحسن الظنَّ بالله، فقد يكون في المحنةِ منحةٌ لا تدري بها."}},{"n":36,"reflection":{"text":"«ودخل معه السجن فتيان قال أحدهما إني أراني أعصر خمرا وقال الآخر إني أراني أحمل فوق رأسي خبزا تأكل الطير منه نبئنا بتأويله إنا نراك من المحسنين»، ودخل السجنَ مع يوسفَ شابّان (خادمان للملك)، قال أحدهما: إني رأيت في المنامِ أعصر عنبًا خمرًا، وقال الآخر: إني رأيت أحمل فوق رأسي خبزًا تأكل الطيرُ منه، أخبرنا بتفسيرِ رؤيانا، إنا نراك من المحسنين في علمك وخلقك؛ ففي هذا أنّ إحسانَ المؤمنِ يظهر أثرُه فيُقصَد ويُوثَق به؛ فأحسن خُلقك وعملك حتى في الشدّة، فالإحسانُ يجعلك موضعَ ثقةٍ ومرجعًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إحسانُ الخُلقِ والعملِ حتى في الشدّة، فيصير المرءُ موضعَ ثقة."},"action":{"text":"أحسن خُلقك وعملك في كلِّ حالٍ حتى في الشدّة، فالإحسانُ يجعلك موضعَ ثقةٍ ومرجعًا للناسِ في حاجاتهم."}},{"n":37,"reflection":{"text":"«قال لا يأتيكما طعام ترزقانه إلا نبأتكما بتأويله قبل أن يأتيكما ذلكما مما علمني ربي إني تركت ملة قوم لا يؤمنون بالله وهم بالآخرة هم كافرون»: قال يوسف: لا يأتيكما طعامٌ تُرزقانه في نومكما أو يقظتكما إلا أخبرتكما بتفسيرِ رؤياكما وما يؤول إليه قبل مجيئه، ذلك مما علّمنيه ربّي (لا من كهانة)، إني تركت دينَ قومٍ لا يؤمنون بالله وهم بالآخرةِ كافرون؛ ففي هذا أنّ يوسفَ نسب العلمَ لله وابتدأ الدعوةَ إلى التوحيدِ قبل تأويلِ الرؤيا؛ فاغتنم الفرصَ للدعوةِ إلى الله، وانسب الفضلَ والعلمَ إليه وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ الفرصِ للدعوةِ إلى الله، ونسبةُ الفضلِ إليه وحده."},"action":{"text":"اغتنم كلَّ فرصةٍ للدعوةِ إلى الله ولو في الشدّة، وانسب العلمَ والفضلَ إلى الله وحده، ولا تنسبه لنفسك."}},{"n":38,"reflection":{"text":"«واتبعت ملة آبائي إبراهيم وإسحاق ويعقوب ما كان لنا أن نشرك بالله من شيء ذلك من فضل الله علينا وعلى الناس ولكن أكثر الناس لا يشكرون»، واتّبعت دينَ آبائي إبراهيمَ وإسحاقَ ويعقوبَ (دينَ التوحيد)، ما كان يصحّ لنا أن نشرك بالله شيئًا؛ ذلك التوحيدُ والنبوّةُ من فضلِ الله علينا (بأن اجتبانا) وعلى الناسِ (بأن أرسلنا إليهم)، ولكنّ أكثرَ الناسِ لا يشكرون هذه النعمة؛ ففي هذا أنّ التوحيدَ أعظمُ فضلٍ يُشكَر، وأنّ اتّباعَ ملّةِ الأنبياءِ نجاة؛ فاشكر نعمةَ التوحيدِ والهداية، والزم ملّةَ الأنبياء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ التوحيدِ والهداية، ولزومُ ملّةِ الأنبياء."},"action":{"text":"اشكر الله على نعمةِ التوحيدِ والهداية، فهي أعظمُ فضلٍ عليك، والزم ملّةَ إبراهيمَ والأنبياءِ ولا تشرك بالله شيئًا."}}]},{"title":"دعوةُ التوحيدِ في السجن، وأنّ الحكمَ لله","range":[39,40],"theme":"المفاضلةُ بين الأربابِ المتفرّقةِ والله الواحدِ القهّار، وأنّ التشريعَ لله","verses":[{"n":39,"reflection":{"text":"«يا صاحبي السجن أأرباب متفرقون خير أم الله الواحد القهار»: يا رفيقيَّ في السجن، أعبادةُ آلهةٍ متعدّدةٍ متفرّقةٍ عاجزةٍ خيرٌ، أم عبادةُ الله الواحدِ الأحدِ القهّارِ الذي قهر كلَّ شيءٍ بقدرته؟ ففي هذا حجّةٌ عقليّةٌ بيّنةٌ على بطلانِ الشركِ وأنّ الواحدَ القهّارَ أحقُّ بالعبادة؛ فاعبد الله الواحدَ القهّارَ وحده، فعبادتُه خيرٌ من عبادةِ آلهةٍ عاجزةٍ متفرّقة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الواحد","القهار"],"heart_state":{"text":"إفرادُ الله الواحدِ القهّارِ بالعبادةِ بالحجّةِ العقلية."},"action":{"text":"اعبد الله الواحدَ القهّارَ وحده، فهو خيرٌ من كلِّ معبودٍ سواه، وتأمّل ببرهانِ عقلك بطلانَ عبادةِ العاجزين."}},{"n":40,"reflection":{"text":"«ما تعبدون من دونه إلا أسماء سميتموها أنتم وآباؤكم ما أنزل الله بها من سلطان إن الحكم إلا لله أمر ألا تعبدوا إلا إياه ذلك الدين القيم ولكن أكثر الناس لا يعلمون»: ما تعبدون من دونِ الله إلا أصنامًا سمّيتموها آلهةً أنتم وآباؤكم بلا حقيقة، ما أنزل الله بعبادتها من حجّةٍ ولا برهان؛ ما الحكمُ والتشريعُ إلا لله وحده، أمر ألّا تعبدوا إلا إيّاه، ذلك هو الدينُ المستقيمُ القويم، ولكنّ أكثرَ الناسِ لا يعلمون فيشركون؛ ففي هذا أنّ الحكمَ والتشريعَ والعبادةَ لله وحده؛ فأفرد الله بالعبادةِ والحكم، ولا تعبد أسماءً لا حقيقةَ لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحكم لله","الدين القيم"],"heart_state":{"text":"إفرادُ الله بالعبادةِ والحكمِ، فذلك الدينُ القويم."},"action":{"text":"اعبد الله وحده واحتكم إلى شرعه، فالحكمُ والتشريعُ والعبادةُ له وحده، وذلك الدينُ القيّم، ولا تعبد أسماءً باطلة."}}]},{"title":"تأويلُ الرؤيا، ونسيانُ الناجي","range":[41,42],"theme":"صدقُ تأويلِ يوسف، وأنّ الاعتمادَ على غيرِ الله يخذل","verses":[{"n":41,"reflection":{"text":"«يا صاحبي السجن أما أحدكما فيسقي ربه خمرا وأما الآخر فيصلب فتأكل الطير من رأسه قضي الأمر الذي فيه تستفتيان»: يا رفيقيَّ في السجن، أمّا أحدكما (الساقي) فيخرج ويسقي سيّده الملكَ خمرًا فيعود إلى عمله، وأمّا الآخر (الخبّاز) فيُصلب فتأكل الطيرُ من رأسه؛ قُضي وفُرغ من الأمرِ الذي تسألان عنه، فهو واقعٌ لا محالة؛ ففي هذا صدقُ يوسفَ في التأويلِ بعلمِ الله، وأنّ ما قدّره الله واقعٌ؛ فاعلم أنّ ما قضاه الله كائنٌ، واطلب العلمَ الصادقَ من أهله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بنفوذِ قضاءِ الله، وطلبُ العلمِ الصادقِ من أهله."},"action":{"text":"أيقن أنّ ما قضاه الله واقعٌ لا محالة، واطلب العلمَ والتأويلَ الصادقَ من أهلِ العلمِ الربّانيّ لا من الكهنةِ والمشعوذين."}},{"n":42,"reflection":{"text":"«وقال للذي ظن أنه ناج منهما اذكرني عند ربك فأنساه الشيطان ذكر ربه فلبث في السجن بضع سنين»، وقال يوسفُ للذي علم أنه ناجٍ (الساقي): اذكر قصّتي ومظلمتي عند سيّدك الملكِ لعلّه يخرجني، فأنسى الشيطانُ الساقيَ أن يذكر يوسفَ عند الملك، فبقي يوسفُ في السجنِ سنواتٍ عدّة؛ ففي هذا أنّ الأخذَ بالأسبابِ مشروع، لكن الاعتمادَ على المخلوقِ وحده قد يخذل، وأنّ الفرجَ بيدِ الله وحده؛ فخذ بالأسبابِ ولا تعتمد عليها، وعلّق قلبك بالله وحده لا بالخلق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأخذُ بالأسبابِ مع تعليقِ القلبِ بالله لا بالمخلوق."},"action":{"text":"خذ بالأسبابِ المشروعة، لكن لا تعتمد بقلبك على مخلوقٍ فيخذلك، بل علّق رجاءك بالله وحده، فالفرجُ بيده."}}]},{"title":"رؤيا الملك، وعجزُ الملأ، وتذكّرُ الناجي","range":[43,45],"theme":"أنّ العلمَ النافعَ عند أهله، وأنّ الله يهيّئ للفرجِ أسبابه","verses":[{"n":43,"reflection":{"text":"«وقال الملك إني أرى سبع بقرات سمان يأكلهن سبع عجاف وسبع سنبلات خضر وأخر يابسات يا أيها الملأ أفتوني في رؤياي إن كنتم للرؤيا تعبرون»، وقال ملكُ مصر: إني رأيت في المنامِ سبعَ بقراتٍ سمانٍ يأكلهنّ سبعٌ هزيلات، وسبعَ سنبلاتٍ خضراءَ وأخرَ يابسات، يا أيها الأشرافُ فسّروا لي رؤياي إن كنتم تحسنون تعبيرها؛ ففي هذا أنّ الله سخّر رؤيا الملكِ لتكون سببًا لخروجِ يوسف؛ فاعلم أنّ الله يسوق الأسبابَ لتحقيقِ ما قدّره لأوليائه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الله يسوق الأسبابَ لتحقيقِ ما قدّره لأوليائه."},"action":{"text":"ثق بأنّ الله يدبّر الأسبابَ ويسخّرها لتحقيقِ الخيرِ لأوليائه، فرؤيا الملكِ كانت بابَ فرجٍ ليوسفَ من حيث لا يُحتسب."}},{"n":44,"reflection":{"text":"«قالوا أضغاث أحلام وما نحن بتأويل الأحلام بعالمين»: قال الملأُ للملك: هذه أخلاطُ أحلامٍ لا معنى لها، وما نحن بتفسيرِ الأحلامِ المختلطةِ بعالمين؛ فأقرّوا بعجزهم؛ ففي هذا أنّ من لا علمَ عنده يعجز، وأنّ الاعترافَ بالجهلِ خيرٌ من التخرّصِ بلا علم؛ فقل «لا أعلم» فيما لا تعلم، ولا تتكلّف الجوابَ بلا علم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعترافُ بالجهلِ فيما لا يُعلَم، وتركُ التكلّفِ بلا علم."},"action":{"text":"قل «لا أعلم» فيما لا تعلم، ولا تتكلّف جوابًا أو فتوى بلا علم، فالاعترافُ بالجهلِ نصفُ العلمِ وأمانة."}},{"n":45,"reflection":{"text":"«وقال الذي نجا منهما وادكر بعد أمة أنا أنبئكم بتأويله فأرسلون»، وقال الساقي الذي نجا من السجنِ وتذكّر يوسفَ بعد مدّةٍ طويلة: أنا أخبركم بتفسيرِ هذه الرؤيا (من عالمٍ أعرفه)، فأرسلوني إليه؛ ففي هذا أنّ الله ذكّره في الوقتِ الذي أراد فيه فرجَ يوسف، وأنّ لكلِّ أمرٍ أجلًا؛ فاطمئن إلى أنّ لكلِّ فرجٍ وقتًا يقدّره الله، فما تأخّر إلا لأجلٍ مسمّى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ لكلِّ فرجٍ وقتًا مقدّرًا عند الله."},"action":{"text":"اطمئن إلى أنّ فرجك يأتي في وقته الذي قدّره الله، فما تأخّر أمرٌ إلا لحكمةٍ وأجلٍ مسمّى، فأحسن الظنَّ به."}}]},{"title":"يوسفُ الصدّيقُ يفسّر الرؤيا ويدبّر","range":[46,49],"theme":"علمُ يوسفَ وحكمتُه في تدبيرِ سنواتِ الرخاءِ والشدّة","verses":[{"n":46,"reflection":{"text":"«يوسف أيها الصديق أفتنا في سبع بقرات سمان يأكلهن سبع عجاف وسبع سنبلات خضر وأخر يابسات لعلي أرجع إلى الناس لعلهم يعلمون»: جاء الساقي يوسفَ فقال: يا يوسفُ أيها الكثيرُ الصدق، فسّر لنا رؤيا السبعِ البقراتِ والسنبلات، لعلّي أرجع إلى الملكِ والناسِ فيعلموا تأويلها وفضلك؛ ففي هذا أنّ يوسفَ عُرف بالصدقِ حتى لُقّب به، وأنّ الصدقَ يرفع صاحبه؛ فالزم الصدقَ حتى تُعرَف به، فالصدّيقُ يُقصَد ويُوثَق به.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الصديق"],"heart_state":{"text":"لزومُ الصدقِ حتى يصير سمةً يُعرَف بها المرء."},"action":{"text":"الزم الصدقَ في قولك وعملك حتى تُعرَف به وتصير موضعَ ثقة، فالصدقُ يرفع صاحبه ويجعله مرجعًا للناس."}},{"n":47,"reflection":{"text":"«قال تزرعون سبع سنين دأبا فما حصدتم فذروه في سنبله إلا قليلا مما تأكلون»: قال يوسف: تزرعون سبعَ سنينَ متتاليةً بجدٍّ واجتهاد، فما حصدتم من الزرعِ فاتركوه في سنبله (ليُحفَظ من السوس) إلا قليلًا تأكلونه؛ ففي هذا حكمةُ يوسفَ في التخطيطِ والادّخارِ للمستقبل، وأنّ الأخذَ بالأسبابِ والتدبيرَ من الدين؛ فخطّط لمستقبلك وادّخر لأوقاتِ الشدّة، فالتدبيرُ الحسنُ من الحكمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأخذُ بالتدبيرِ والادّخارِ الحسنِ لأوقاتِ الشدّة."},"action":{"text":"دبّر أمرك وادّخر لأوقاتِ الحاجةِ والشدّة، فالتخطيطُ الحسنُ والأخذُ بالأسبابِ من الحكمةِ التي لا تنافي التوكّل."}},{"n":48,"reflection":{"text":"«ثم يأتي من بعد ذلك سبع شداد يأكلن ما قدمتم لهن إلا قليلا مما تحصنون»: ثم يأتي بعد سنواتِ الخصبِ سبعُ سنينٍ مجدبةٍ شديدةٍ يأكل أهلُها ما ادّخرتم لهنّ إلا قليلًا تحفظونه للبذر؛ ففي هذا أنّ الرخاءَ قد يعقبه شدّةٌ فيُستعدُّ له، وأنّ الحكمةَ في الادّخارِ وقتَ السَّعة؛ فاستعدّ في رخائك لشدّتك، ولا تسرف في النعمةِ فتندم في الشدّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ في الرخاءِ للشدّة، وعدمُ الإسرافِ في النعمة."},"action":{"text":"استعدّ في زمنِ الرخاءِ لأوقاتِ الشدّةِ بالادّخارِ والاقتصاد، ولا تسرف في النعمةِ فتندم عند شحّها."}},{"n":49,"reflection":{"text":"«ثم يأتي من بعد ذلك عام فيه يغاث الناس وفيه يعصرون»: ثم يأتي بعد سنواتِ الجدبِ عامٌ يُغاث فيه الناسُ بالمطرِ والخصب، ويعصرون فيه العنبَ والزيتونَ لكثرةِ الخير؛ ففي هذا بشارةٌ بالفرجِ بعد الشدّة، وأنّ يوسفَ زاد من علمِه بشارةً لم تُسأل؛ ففي هذا أنّ بعد الشدّةِ فرجًا، وأنّ الإحسانَ في العطاءِ أن تزيد على المطلوبِ خيرًا؛ فأبشر بأنّ مع العسرِ يسرًا، وزِد في إحسانك على ما يُطلب منك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"البشارةُ بالفرجِ بعد الشدّة، والزيادةُ في الإحسانِ على المطلوب."},"action":{"text":"أبشر بأنّ بعد الشدّةِ فرجًا ويسرًا، وأحسن في عطائك بأن تزيد على ما يُطلب منك خيرًا كما زاد يوسفُ البشارة."}}]},{"title":"طلبُ الملكِ يوسفَ، وإصرارُه على براءته","range":[50,53],"theme":"عزّةُ يوسفَ إذ آثر تبرئةَ عرضه، واعترافُ المرأةِ بالحقّ، وتواضعُه","verses":[{"n":50,"reflection":{"text":"«وقال الملك ائتوني به فلما جاءه الرسول قال ارجع إلى ربك فاسأله ما بال النسوة اللاتي قطعن أيديهن إن ربي بكيدهن عليم»، وقال الملكُ لمّا أعجبه تأويلُ يوسف: ائتوني به، فلما جاءه رسولُ الملك يدعوه للخروج، قال يوسفُ: ارجع إلى سيّدك الملكِ فاسأله عن حالِ النسوةِ اللاتي قطّعن أيديهنّ لتظهر براءتي أولًا، إنّ ربّي بكيدهنّ عليمٌ؛ ففي هذا صبرُ يوسفَ وحرصُه على أن يخرج بريءَ الساحةِ لا متّهمًا، وعزّةُ نفسه؛ ففي هذا أنّ صونَ العرضِ وتبرئةَ الساحةِ من الحكمة؛ فاحرص على أن تخرج من التهمةِ بريئًا، ولا تعجل حتى يظهر الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على تبرئةِ الساحةِ وصونِ العرضِ بالصبرِ والحكمة."},"action":{"text":"احرص على أن تخرج من كلِّ تهمةٍ بريءَ الساحةِ بالحقّ، ولا تعجل، فصونُ العرضِ وتبرئةُ النفسِ بالحكمةِ من العزّة."}},{"n":51,"reflection":{"text":"«قال ما خطبكن إذ راودتن يوسف عن نفسه قلن حاش لله ما علمنا عليه من سوء قالت امرأت العزيز الآن حصحص الحق أنا راودته عن نفسه وإنه لمن الصادقين»: قال الملكُ للنسوة: ما شأنكنّ حين راودتنّ يوسفَ عن نفسه؟ قلن: تنزيهًا لله ما علمنا عليه من سوء؛ فاعترفن ببراءته، وقالت امرأةُ العزيزِ معترفةً: الآن ظهر الحقُّ وتبيّن، أنا راودته عن نفسه وامتنع، وإنه لمن الصادقين؛ ففي هذا أنّ الحقَّ يظهر ولو بعد حين، وأنّ الصبرَ يُثمر البراءة؛ فاصبر على الظلمِ حتى يُظهر الله الحقَّ ويبرّئك، فالحقُّ لا يُدفن أبدًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["حصحص الحق"],"heart_state":{"text":"اليقينُ بأنّ الحقَّ يظهر بالصبر، وأنّ الصبرَ يُثمر البراءة."},"action":{"text":"اصبر على الظلمِ والتهمةِ حتى يُظهر الله الحقَّ ويبرّئك على رؤوسِ الخصوم، فالحقُّ لا يُدفن ولو بعد حين."}},{"n":52,"reflection":{"text":"«ذلك ليعلم أني لم أخنه بالغيب وأن الله لا يهدي كيد الخائنين»: قال يوسف (أو امرأةُ العزيز): ذلك الاعترافُ ليعلم العزيزُ أني لم أخنه في أهله وهو غائبٌ عني، وأنّ الله لا يوفّق كيدَ الخائنين بل يفضحه؛ ففي هذا أنّ حفظَ الأمانةِ في الغيبِ من كمالِ الدين، وأنّ الخيانةَ لا تُفلح؛ فاحفظ الأمانةَ في الغيبِ كما تحفظها في الحضور، فالله لا يهدي كيدَ الخائنين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ الأمانةِ في الغيبِ، واليقينُ بأنّ الخيانةَ لا تُفلح."},"action":{"text":"احفظ الأماناتِ والحقوقَ في السرِّ والغيبِ كما تحفظها في العلن، واعلم أنّ الله لا يوفّق كيدَ الخائنين بل يفضحه."}},{"n":53,"reflection":{"text":"«وما أبرئ نفسي إن النفس لأمارة بالسوء إلا ما رحم ربي إن ربي غفور رحيم»: قال يوسف (أو المرأة) تواضعًا: وما أزكّي نفسي وأبرّئها من الميلِ إلى السوء، فإنّ النفسَ البشريّةَ كثيرةُ الأمرِ بالسوءِ داعيةٌ إليه، إلا نفسًا رحمها ربّي فعصمها؛ إنّ ربّي غفورٌ لمن تاب رحيمٌ به؛ ففي هذا أنّ العصمةَ من السوءِ برحمةِ الله لا بحولِ النفس، وأنّ التواضعَ وعدمَ تزكيةِ النفسِ من صفاتِ الكُمّل؛ فلا تزكِّ نفسك ولا تأمن مكرها، والتجئ إلى رحمةِ الله يعصمك من سوئها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["النفس الأمارة","الغفور","الرحيم"],"heart_state":{"text":"عدمُ تزكيةِ النفسِ والاعتصامُ برحمةِ الله من أمرها بالسوء."},"action":{"text":"لا تزكِّ نفسك ولا تأمن ميلها إلى السوء، بل اتّهمها والتجئ إلى رحمةِ الله أن يعصمك، فالنفسُ أمّارةٌ بالسوءِ إلا من رحم."}}]},{"title":"تمكينُ يوسفَ في الأرض","range":[54,57],"theme":"استخلاصُ الملكِ ليوسف، وأمانتُه، وأنّ الله لا يضيع أجرَ المحسنين","verses":[{"n":54,"reflection":{"text":"«وقال الملك ائتوني به أستخلصه لنفسي فلما كلمه قال إنك اليوم لدينا مكين أمين»، وقال الملكُ لمّا ظهرت براءةُ يوسفَ وفضلُه: ائتوني به أجعله خالصًا لي ومن خاصّتي، فلما كلّمه وعرف علمَه وعقله قال: إنك اليوم عندنا ذو مكانةٍ ومنزلةٍ أمينٌ مؤتمَنٌ على كلِّ شيء؛ ففي هذا أنّ العلمَ والأمانةَ يرفعان صاحبهما، وأنّ الله رفع يوسفَ بعد المحن؛ فاجمع العلمَ والأمانة، فبهما تُرفع منزلتك عند الله والناس.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ العلمَ والأمانةَ يرفعان صاحبهما عند الله والناس."},"action":{"text":"اجمع بين العلمِ والأمانةِ في نفسك، فبهما تُرفع منزلتك وتصير موضعَ ثقةٍ وتمكين، كما رُفع يوسفُ بعد المحن."}},{"n":55,"reflection":{"text":"«قال اجعلني على خزائن الأرض إني حفيظ عليم»: قال يوسفُ للملك: اجعلني واليًا على خزائنِ أرضِ مصرَ (أموالِها وأقواتها)، إني حفيظٌ أمينٌ على ما أتولّاه عليمٌ بتدبيره وتصريفه؛ ففي هذا أنّ من علم في نفسه الكفاءةَ والأمانةَ في أمرٍ عامٍّ جاز أن يطلبه لينفع الناس، وأنّ الولايةَ أمانةٌ تحتاج حفظًا وعلمًا؛ فإن قدرت على نفعِ الناسِ بأمانةٍ وكفاءةٍ فاطلب ذلك بنيّةِ الإصلاحِ لا الجاه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["حفيظ","عليم"],"heart_state":{"text":"أنّ الولايةَ أمانةٌ تحتاج حفظًا وعلمًا، وطلبُها لنفعِ الناس."},"action":{"text":"إن علمت في نفسك كفاءةً وأمانةً لنفعِ الناس فاطلب موضعك بنيّةِ الإصلاحِ لا الجاه، فالولايةُ أمانةٌ تحتاج حفظًا وعلمًا."}},{"n":56,"reflection":{"text":"«وكذلك مكنا ليوسف في الأرض يتبوأ منها حيث يشاء نصيب برحمتنا من نشاء ولا نضيع أجر المحسنين»، وكذلك مكّنّا ليوسفَ في أرضِ مصرَ ينزل منها حيث يشاء بعد السجنِ والرقّ، نصيب برحمتنا من نشاء من عبادنا، ولا نضيع أجرَ المحسنين بل نجزيهم أحسنَ الجزاء؛ ففي هذا أنّ عاقبةَ الصبرِ والإحسانِ التمكينُ والرفعة، وأنّ الله لا يضيع أجرَ محسن؛ فأحسن واصبر، فعاقبةُ الإحسانِ رحمةٌ وتمكينٌ، والله لا يضيع أجرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لا نضيع أجر المحسنين"],"heart_state":{"text":"أنّ عاقبةَ الصبرِ والإحسانِ التمكينُ، وأنّ الله لا يضيع الأجر."},"action":{"text":"أحسن واصبر على البلاء، فعاقبةُ الإحسانِ والصبرِ رحمةٌ وتمكين، والله لا يضيع أجرَ المحسنين بل يرفعهم."}},{"n":57,"reflection":{"text":"«ولأجر الآخرة خير للذين آمنوا وكانوا يتقون»، ولثوابُ الآخرةِ الذي أعدّه الله للمؤمنين المتقين خيرٌ وأبقى من تمكينِ الدنيا ومُلكها؛ ففي هذا أنّ ما ناله يوسفُ في الدنيا عظيم، لكنّ أجرَ الآخرةِ أعظمُ وأبقى، وأنّ العبرةَ بالإيمانِ والتقوى؛ فاعمل لأجرِ الآخرةِ فهو خيرٌ وأبقى، ولا تجعل التمكينَ الدنيويَّ غايتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["أجر الآخرة خير"],"heart_state":{"text":"إيثارُ أجرِ الآخرةِ الباقي على تمكينِ الدنيا الفاني."},"action":{"text":"اعمل لأجرِ الآخرةِ فهو خيرٌ وأبقى من كلِّ تمكينٍ دنيويّ، والزم الإيمانَ والتقوى، ولا تجعل الدنيا منتهى مطلبك."}}]},{"title":"قدومُ الإخوة، وحكمةُ يوسفَ في استقدامِ أخيه","range":[58,60],"theme":"معرفةُ يوسفَ لإخوته وجهلُهم به، وحسنُ تدبيره لجمعِ شمله","verses":[{"n":58,"reflection":{"text":"«وجاء إخوة يوسف فدخلوا عليه فعرفهم وهم له منكرون»، وجاء إخوةُ يوسفَ إلى مصرَ يطلبون الميرةَ (الطعام) في سنيِّ القحط، فدخلوا عليه فعرفهم يوسفُ (لثباتِ صورتهم في ذهنه) وهم لا يعرفونه (لتغيّره وطولِ الفراقِ وعلوِّ منصبه)؛ ففي هذا بدءُ تحقّقِ رؤيا يوسف، وأنّ الله يدبّر اللقاءَ في وقته؛ فاطمئن إلى أنّ ما وعد الله به واقعٌ في وقته المقدّر، فقد جمع الله يوسفَ بإخوته بعد فراقٍ طويل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ وعدَ الله واقعٌ، وأنه يجمع الأحبّةَ في وقته."},"action":{"text":"ثق بأنّ الله يحقّق وعده ويجمع ما تفرّق في وقته المقدّر، كما جمع يوسفَ بإخوته بعد سنينَ من الفراق."}},{"n":59,"reflection":{"text":"«ولما جهزهم بجهازهم قال ائتوني بأخ لكم من أبيكم ألا ترون أني أوفي الكيل وأنا خير المنزلين»، ولما أعطاهم يوسفُ حاجتهم من الطعامِ وأكرمهم، قال: ائتوني في المرّةِ القادمةِ بأخيكم من أبيكم (بنيامين)، ألا ترون أني أوفّي الكيلَ تامًّا وأنا خيرُ من ينزل الأضياف ويكرمهم؟ فرغّبهم بحسنِ المعاملةِ ليعودوا بأخيه؛ ففي هذا حسنُ سياسةِ يوسفَ وإيفائه الحقوقَ وإكرامه؛ فأوفِ الناسَ حقوقهم وأحسن ضيافتهم، فبالإحسانِ تبلغ مقاصدك الحسنة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيفاءُ الحقوقِ وحسنُ الضيافةِ وسيلةً لبلوغِ المقاصدِ الحسنة."},"action":{"text":"أوفِ الناسَ حقوقهم كاملةً وأحسن معاملتهم وضيافتهم، فبالإحسانِ والوفاءِ تبلغ مقاصدك الحسنةَ وتكسب القلوب."}},{"n":60,"reflection":{"text":"«فإن لم تأتوني به فلا كيل لكم عندي ولا تقربون»: فإن لم تأتوني بأخيكم فلا نصيبَ لكم من الكيلِ عندي في المستقبل، ولا تقربوا بلدي؛ فجمع بين الترغيبِ (الإكرام) والترهيبِ (المنع) ليحملهم على إحضارِ أخيه؛ ففي هذا أنّ الحكمةَ تجمع بين الترغيبِ والترهيبِ لبلوغِ المصلحة؛ فاجمع في تدبيرك بين الترغيبِ والترهيبِ بحكمةٍ لتحقيقِ الخير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الترغيبِ والترهيبِ بحكمةٍ لتحقيقِ المصلحة."},"action":{"text":"ادّبر أمورك بحكمةٍ تجمع بين الترغيبِ والترهيبِ بحسبِ المصلحة، كما فعل يوسفُ ليجمع شمله بأخيه."}}]},{"title":"ردُّ البضاعة، ورجوعُ الإخوةِ إلى أبيهم","range":[61,64],"theme":"لطفُ يوسفَ بردِّ بضاعتهم، وتوكّلُ يعقوبَ على خيرِ الحافظين","verses":[{"n":61,"reflection":{"text":"«قالوا سنراود عنه أباه وإنا لفاعلون»: قال الإخوةُ: سنطلب أخانا من أبيه ونجتهد في إقناعه بإرساله، وإنا لفاعلون ذلك لا محالة؛ ففي هذا عزمهم على تحصيلِ المطلوبِ بالسعيِ والمراودة؛ فاسعَ في تحقيقِ الخيرِ بالأسبابِ المشروعة، واعزم على ما فيه المصلحة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"السعيُ في تحصيلِ الخيرِ بالأسبابِ المشروعةِ والعزم."},"action":{"text":"اسعَ في تحصيلِ ما فيه مصلحتك بالأسبابِ المشروعةِ والعزمِ الصادق، ولا تتواكل عن بذلِ الوسع."}},{"n":62,"reflection":{"text":"«وقال لفتيانه اجعلوا بضاعتهم في رحالهم لعلهم يعرفونها إذا انقلبوا إلى أهلهم لعلهم يرجعون»، وقال يوسفُ لغلمانه: ضعوا ثمنَ طعامهم (بضاعتهم) خفيةً في أمتعتهم، لعلّهم يجدونها إذا رجعوا إلى أهلهم فيعرفون كرمي، فيدعوهم ذلك إلى الرجوعِ إليّ (وليكون لهم مالٌ يأتون به مرّةً أخرى)؛ ففي هذا لطفُ يوسفَ وكرمُه الخفيّ، وحسنُ تدبيره؛ فأحسن إلى الناسِ في السرِّ كما في العلن، وابذل المعروفَ من غيرِ منٍّ ولا أذًى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ في السرِّ وبذلُ المعروفِ من غيرِ منٍّ ولا أذًى."},"action":{"text":"أحسن إلى الناسِ في السرِّ كما في العلن، وابذل المعروفَ بلطفٍ من غيرِ منٍّ ولا أذًى، فذاك أكرمُ الإحسان."}},{"n":63,"reflection":{"text":"«فلما رجعوا إلى أبيهم قالوا يا أبانا منع منا الكيل فأرسل معنا أخانا نكتل وإنا له لحافظون»: فلما رجعوا إلى أبيهم قالوا: يا أبانا سيُمنع منا الطعامُ في المرّةِ القادمةِ إن لم نأتِ بأخينا، فأرسله معنا نأخذ الكيلَ، وإنا له لحافظون من كلِّ سوء؛ ففي هذا إلحاحهم على أبيهم بالحاجةِ والوعدِ بالحفظ؛ ففي هذا أنّ الحاجةَ قد تدعو إلى ما يُخشى منه، فيُتوكّل على الله؛ فإذا اضطررت إلى أمرٍ فيه مخاطرةٌ فخذ بالحيطةِ وتوكّل على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأخذُ بالحيطةِ عند الحاجةِ مع التوكّلِ على الله."},"action":{"text":"إذا دعتك الحاجةُ إلى أمرٍ فيه مخاطرةٌ فخذ بأسبابِ الحيطةِ والحفظ، ثم توكّل على الله، فالحفظُ الحقيقيُّ بيده."}},{"n":64,"reflection":{"text":"«قال هل آمنكم عليه إلا كما أمنتكم على أخيه من قبل فالله خير حافظا وهو أرحم الراحمين»: قال يعقوب: هل آمنكم على بنيامينَ إلا كما ائتمنتكم على يوسفَ من قبلُ فخانوا الأمانة؟ ثم فوّض الأمرَ لله قائلًا: فالله خيرٌ حفظًا لعبده من كلِّ حافظ، وهو أرحمُ الراحمين بي يرحم شيبتي وحزني؛ ففي هذا أنّ الحفظَ الحقيقيَّ من الله وحده، وأنّ المؤمنَ يفوّض أمره لأرحمِ الراحمين؛ فاجعل حفظك على الله وحده، وفوّض أمرك لأرحمِ الراحمين، فحفظُه خيرُ حفظ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["خير حافظا","أرحم الراحمين"],"heart_state":{"text":"تفويضُ الحفظِ إلى الله خيرِ الحافظين وأرحمِ الراحمين."},"action":{"text":"فوّض حفظَ نفسك وأحبّتك إلى الله، فهو خيرٌ حافظًا من كلِّ أحد وأرحمُ الراحمين، وعلّق قلبك بحفظه لا بحفظِ الخلق."}}]},{"title":"البضاعةُ المردودة، وأخذُ الموثقِ على الأخ","range":[65,66],"theme":"فرحُ الإخوةِ بردِّ بضاعتهم، وحرصُ يعقوبَ بأخذِ العهدِ الموثّق بالله","verses":[{"n":65,"reflection":{"text":"«ولما فتحوا متاعهم وجدوا بضاعتهم ردت إليهم قالوا يا أبانا ما نبغي هذه بضاعتنا ردت إلينا ونمير أهلنا ونحفظ أخانا ونزداد كيل بعير ذلك كيل يسير»، ولما فتحوا أمتعتهم وجدوا ثمنهم رُدّ إليهم كرامةً من العزيز، قالوا فرحين: يا أبانا ماذا نطلب أكثرَ من هذا؟ هذه بضاعتنا رُدّت إلينا، وسنجلب الطعامَ لأهلنا ونحفظ أخانا ونزداد حِملَ بعيرٍ بسببِ أخينا؛ ذلك كيلٌ سهلٌ يسيرٌ على الملك؛ ففي هذا أنّ الكرمَ يكسب القلوبَ ويزيل الريبة؛ فقابل الإحسانَ بالشكرِ وحسنِ الظنّ، ولا تنسَ فضلَ من أحسن إليك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الإحسانِ وحسنُ الظنِّ بالمحسنِ، وذكرُ فضله."},"action":{"text":"اشكر من أحسن إليك واذكر فضله بحسنِ ظنّ، فالكرمُ يكسب القلوبَ، وقابل الإحسانَ بالإحسانِ والثناءِ الحسن."}},{"n":66,"reflection":{"text":"«قال لن أرسله معكم حتى تؤتون موثقا من الله لتأتنني به إلا أن يحاط بكم فلما آتوه موثقهم قال الله على ما نقول وكيل»: قال يعقوب: لن أرسل بنيامينَ معكم حتى تعطوني عهدًا مؤكّدًا بالله لتردّنّه إليّ إلا أن تُغلَبوا جميعًا فلا تقدروا؛ فلما أعطوه عهدهم الموثّق، قال: الله على ما نقول شهيدٌ حفيظٌ وكيلٌ يراقب عهودنا؛ ففي هذا أنّ توثيقَ العهودِ بالله من الحزم، وأنّ الله شاهدٌ على العهود؛ فوثّق عهودك واستشهد الله عليها، واحفظ ما عاهدت عليه، فالله وكيلٌ رقيب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الوكيل"],"heart_state":{"text":"توثيقُ العهودِ بالله والحرصُ على الوفاءِ بها."},"action":{"text":"وثّق عهودك ومواثيقك واستشهد الله عليها، واحفظ ما عاهدت عليه، فالله شاهدٌ وكيلٌ على ما تقول وتعاهد."}}]},{"title":"وصيّةُ يعقوب، والتوكّلُ على الله وحده","range":[67,68],"theme":"الأخذُ بالأسبابِ مع التوكّلِ على الله، وأنّ الحكمَ لله وحده","verses":[{"n":67,"reflection":{"text":"«وقال يا بني لا تدخلوا من باب واحد وادخلوا من أبواب متفرقة وما أغني عنكم من الله من شيء إن الحكم إلا لله عليه توكلت وعليه فليتوكل المتوكلون»، وقال يعقوبُ لبنيه: لا تدخلوا مصرَ من بابٍ واحدٍ (خشيةَ العينِ لجمالهم وكثرتهم) وادخلوا من أبوابٍ متفرّقة، وما أدفع عنكم بهذا التدبيرِ قضاءَ الله من شيءٍ إن أراده، ما الحكمُ والقضاءُ إلا لله وحده، عليه توكّلت وعليه فليعتمد المتوكّلون؛ ففي هذا أنّ الأخذَ بالأسبابِ لا ينافي التوكّل، وأنّ التوكّلَ على الله وحده؛ فخذ بالأسبابِ الحسيّةِ وتوكّل على الله وحده، فالحكمُ له والاعتمادُ عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحكم لله"],"heart_state":{"text":"الجمعُ بين الأخذِ بالأسبابِ والتوكّلِ على الله وحده."},"action":{"text":"خذ بالأسبابِ المشروعةِ في أمورك، ثم توكّل على الله وحده، فالأخذُ بالسببِ لا ينافي التوكّل، والحكمُ كلُّه لله."}},{"n":68,"reflection":{"text":"«ولما دخلوا من حيث أمرهم أبوهم ما كان يغني عنهم من الله من شيء إلا حاجة في نفس يعقوب قضاها وإنه لذو علم لما علمناه ولكن أكثر الناس لا يعلمون»، ولما دخلوا من الأبوابِ المتفرّقةِ كما أمرهم أبوهم، ما كان ذلك التدبيرُ ليدفع عنهم قضاءَ الله لو أراد بهم شيئًا، ولكنها كانت حاجةً وشفقةً في نفسِ يعقوبَ قضاها ليطمئن قلبُه؛ وإنه لصاحبُ علمٍ نافعٍ علّمناه إيّاه (فيعمل بالأسبابِ ويتوكّل)، ولكنّ أكثرَ الناسِ لا يعلمون هذا التوازن؛ ففي هذا أنّ العلمَ النافعَ يجمع بين الأخذِ بالسببِ والتوكّل؛ فاجمع بين الأخذِ بالأسبابِ والتوكّلِ على الله، فذاك من علمِ الراسخين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ذو علم"],"heart_state":{"text":"أنّ العلمَ النافعَ يجمع بين الأخذِ بالأسبابِ والتوكّل."},"action":{"text":"اجمع في حياتك بين الأخذِ بالأسبابِ الحسيّةِ والتوكّلِ على الله، فذاك التوازنُ من العلمِ النافعِ الذي يجهله أكثرُ الناس."}}]},{"title":"يوسفُ يؤوي أخاه، وتدبيرُ السقاية","range":[69,70],"theme":"لطفُ يوسفَ بأخيه، وحيلتُه المشروعةُ لإبقائه عنده","verses":[{"n":69,"reflection":{"text":"«ولما دخلوا على يوسف آوى إليه أخاه قال إني أنا أخوك فلا تبتئس بما كانوا يعملون»، ولما دخل الإخوةُ على يوسفَ ومعهم بنيامينُ، ضمّ يوسفُ أخاه الشقيقَ إليه وأخبره سرًّا: إني أنا أخوك يوسف، فلا تحزن بما كان إخوتنا يعملون بنا من الأذى والحسد؛ ففي هذا لطفُ يوسفَ بأخيه وتسليتُه له، وأنّ اللقاءَ بعد الفراقِ فرحٌ؛ فسلِّ الحزينَ وواسِ المكروب، وأخبر أخاك بما يطمئن قلبه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مواساةُ الحزينِ وتطييبُ قلبِ المكروبِ بالبشرى."},"action":{"text":"واسِ الحزينَ وطيّب قلبَ المكروبِ بما يفرّج همّه، كما آوى يوسفُ أخاه وطمأنه، ولا تدع أخاك في وحشةٍ وحزن."}},{"n":70,"reflection":{"text":"«فلما جهزهم بجهازهم جعل السقاية في رحل أخيه ثم أذن مؤذن أيتها العير إنكم لسارقون»: فلما هيّأ لهم طعامهم، وضع يوسفُ إناءَ الملكِ الذي يُكال به (السقاية) في متاعِ أخيه بنيامينَ خفيةً (باتّفاقٍ معه)، ثم نادى منادٍ: أيتها القافلةُ إنكم لسارقون؛ وكان هذا تدبيرًا بوحيٍ من الله ليبقيَ أخاه عنده بحكمٍ يقرّه الإخوة؛ ففي هذا أنّ الحيلةَ المباحةَ لتحقيقِ مقصودٍ حسنٍ جائزة، وأنّ الله يهيّئ الأسباب؛ فاطلب مقاصدك الحسنةَ بالطرقِ المشروعة، واعلم أنّ الله يدبّر لك ما فيه الخير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ المقاصدِ الحسنةِ بالطرقِ المشروعة، والثقةُ بتدبيرِ الله."},"action":{"text":"اطلب مقاصدك الحسنةَ بالوسائلِ المشروعة، وثق بأنّ الله يدبّر لك الخيرَ ويهيّئ أسبابه من حيث لا تحتسب."}}]},{"title":"التفتيشُ والاتّهام، ورفعُ درجاتِ يوسف","range":[71,76],"theme":"براءةُ الإخوةِ الظاهرة، وكيدُ الله ليوسف، وأنّ فوقَ كلِّ عالمٍ أعلم","verses":[{"n":71,"reflection":{"text":"«قالوا وأقبلوا عليهم ماذا تفقدون»: قال إخوةُ يوسفَ مقبلين على المنادين والمفتّشين مستنكرين: ماذا فقدتم حتى تتّهمونا بالسرقة؟ ففي هذا مواجهتُهم للتهمةِ بالسؤالِ لبراءتهم في ظاهرهم؛ ففي هذا أنّ من اتُّهم بباطلٍ له أن يستوضح ويدفع عن نفسه؛ فادفع عن نفسك التهمةَ الباطلةَ بالبيانِ والاستيضاح، ولا تسكت عن الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"دفعُ التهمةِ الباطلةِ بالبيانِ والاستيضاح."},"action":{"text":"إذا اتُّهمت بباطلٍ فادفعه بالبيانِ والاستيضاحِ الهادئ، ولا تسكت عن حقّك، فالبيانُ سبيلُ ظهورِ البراءة."}},{"n":72,"reflection":{"text":"«قالوا نفقد صواع الملك ولمن جاء به حمل بعير وأنا به زعيم»: قال المنادون: نفقد إناءَ الملكِ الذي يُكال به، ولمن جاء به حِملُ بعيرٍ من الطعامِ جائزةً، وأنا بذلك كفيلٌ ضامن؛ ففي هذا إعلانُ الجائزةِ لمن يردّه، والكفالةُ بالوفاء؛ ففي هذا مشروعيّةُ الجُعالةِ (الجائزةِ على العمل) والضمان؛ فأوفِ بما ضمنت والتزمت، فالكفيلُ غارمٌ ملتزم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ بالضمانِ والالتزام، ومشروعيّةُ الجائزةِ على العمل."},"action":{"text":"أوفِ بما تضمنه وتلتزم به، فالكفيلُ ملتزمٌ بما ضمن، والجائزةُ على العملِ النافعِ مشروعةٌ إذا وُفّي بها."}},{"n":73,"reflection":{"text":"«قالوا تالله لقد علمتم ما جئنا لنفسد في الأرض وما كنا سارقين»: قال إخوةُ يوسفَ حالفين: والله لقد عرفتم من سيرتنا وحالنا حين دخلنا أننا ما جئنا لنفسد في أرضكم، وما كنا سارقين قطّ؛ فاحتجّوا ببراءةِ سيرتهم؛ ففي هذا أنّ حسنَ السيرةِ حجّةٌ لصاحبها عند التهمة؛ فاحفظ سيرتك نقيّةً، فحسنُ السمعةِ حصنٌ يدفع عنك التهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ السيرةِ النقيّةِ، فحسنُ السمعةِ حجّةٌ عند التهمة."},"action":{"text":"احفظ سيرتك وسمعتك نقيّةً، فحسنُ السيرةِ حصنٌ يدفع عنك التهمَ ويشهد لك بالبراءةِ عند الاتّهام."}},{"n":74,"reflection":{"text":"«قالوا فما جزاؤه إن كنتم كاذبين»: قال أعوانُ يوسف: فما عقوبةُ السارقِ عندكم إن ظهر كذبكم ووُجد المسروقُ معكم؟ فأرادوا أن يُلزموهم بحكمهم أنفسهم؛ ففي هذا حكمةُ إلزامِ الخصمِ بما يقرّه هو؛ ففي هذا أنّ إقامةَ الحجّةِ على الخصمِ بما يلتزمه أبلغُ في إفحامه؛ فأقم الحجّةَ على المخالفِ بما يقرّ هو به، فذاك أقطعُ للنزاع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إقامةُ الحجّةِ على الخصمِ بما يلتزمه هو نفسه."},"action":{"text":"إذا حاججت مخالفًا فألزمه بما يقرّ هو به، فذاك أبلغُ في إقامةِ الحجّةِ وأقطعُ للنزاعِ والجدال."}},{"n":75,"reflection":{"text":"«قالوا جزاؤه من وجد في رحله فهو جزاؤه كذلك نجزي الظالمين»: قال إخوةُ يوسف: عقوبةُ السارقِ في شريعتنا (شريعةِ يعقوب) أنّ من وُجد المسروقُ في متاعه فهو يُسترقّ جزاءً لسرقته، كذلك نجزي الظالمين بالسرقة؛ فحكموا على أنفسهم بحكمهم؛ ففي هذا أنّ الله ساق الأمرَ ليحكموا بما يوافق مقصدَ يوسف؛ ففي هذا لطفُ تدبيرِ الله؛ فاطمئن إلى أنّ الله يدبّر الأمورَ بحكمةٍ تبلغ بها المقاصدُ الحسنة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى لطفِ تدبيرِ الله في سَوقِ الأمورِ لمقاصدها."},"action":{"text":"اطمئن إلى أنّ الله يدبّر الأمورَ بحكمةٍ خفيّةٍ تبلغ بها المقاصدُ الحسنة، فسلّم أمرك له وأحسن ظنّك بتدبيره."}},{"n":76,"reflection":{"text":"«فبدأ بأوعيتهم قبل وعاء أخيه ثم استخرجها من وعاء أخيه كذلك كدنا ليوسف ما كان ليأخذ أخاه في دين الملك إلا أن يشاء الله نرفع درجات من نشاء وفوق كل ذي علم عليم»: فبدأ يوسفُ بتفتيشِ أوعيةِ إخوته قبل وعاءِ أخيه (دفعًا للتهمةِ عنه)، ثم استخرج الإناءَ من وعاءِ أخيه؛ كذلك دبّرنا ليوسفَ هذا التدبيرَ اللطيف، فما كان يمكنه أن يأخذ أخاه بحكمِ ملكِ مصر (إذ ليس فيه الاسترقاق) لولا أن هيّأ الله له الحكمَ بشريعةِ يعقوب؛ نرفع بالعلمِ والحكمةِ درجاتِ من نشاء، وفوق كلِّ صاحبِ علمٍ من هو أعلمُ منه حتى ينتهيَ العلمُ إلى الله العليم؛ ففي هذا أنّ العلمَ يرفع الدرجات، وأنّ فوق كلِّ عالمٍ أعلم، والله فوق الجميع؛ فاطلب العلمَ يرفعك الله، وتواضع فما أُوتيت من العلمِ إلا قليلًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فوق كل ذي علم عليم"],"heart_state":{"text":"طلبُ العلمِ الرافعِ للدرجات، والتواضعُ فوق كلِّ عالمٍ أعلم."},"action":{"text":"اطلب العلمَ فإنه يرفع درجاتك، وتواضع به فإنّ فوق كلِّ ذي علمٍ أعلمَ منه، وعلمُ الله فوق الجميع، فلا تغترّ بعلمك."}}]},{"title":"اتّهامُ الإخوة، وعفّةُ يوسفَ عن الظلم","range":[77,79],"theme":"كتمُ يوسفَ لأذاهم، ورفضُه أخذَ بريءٍ مكانَ المتّهم","verses":[{"n":77,"reflection":{"text":"«قالوا إن يسرق فقد سرق أخ له من قبل فأسرها يوسف في نفسه ولم يبدها لهم قال أنتم شر مكانا والله أعلم بما تصفون»: قال إخوةُ يوسف تبرّؤًا: إن يسرق بنيامينُ فقد سرق أخوه (يوسف) من قبل! فتنقّصوا يوسفَ وأخاه؛ فأخفى يوسفُ هذه الكلمةَ ولم يظهر لهم ما في نفسه، وقال في نفسه: أنتم شرٌّ منزلةً بما فعلتم، والله أعلم بما تصفونه من الكذب؛ ففي هذا حلمُ يوسفَ وكظمُه للغيظِ وسترُه؛ فاكظم غيظك واستر ما لا ينبغي إظهاره، ولا تقابل الإساءةَ بمثلها في وقتِ القدرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"كظمُ الغيظِ وسترُ الإساءةِ، وعدمُ مقابلتِها في وقتِ القدرة."},"action":{"text":"اكظم غيظك عند الإساءةِ إليك، واستر ما لا ينبغي إظهاره، ولا تقابل الإساءةَ بمثلها ولو قدرت، فالحلمُ من شيمِ الكرام."}},{"n":78,"reflection":{"text":"«قالوا يا أيها العزيز إن له أبا شيخا كبيرا فخذ أحدنا مكانه إنا نراك من المحسنين»: قال الإخوةُ ليوسف (وهم لا يعرفونه): يا أيها العزيزُ إنّ لهذا الغلامِ (بنيامين) أبًا شيخًا كبيرًا يحبّه ويشقّ عليه فراقُه، فخذ أحدنا رهينةً مكانه، إنا نراك من المحسنين في معاملتك فأحسن إلينا؛ ففي هذا توسّلهم بالإحسانِ لقضاءِ حاجتهم؛ ففي هذا أنّ الإحسانَ يُتوسّل به، وأنّ رعايةَ الوالدِ الكبيرِ مقصدٌ نبيل؛ فتوسّل إلى المحسنِ بإحسانه، وراعِ حقَّ الوالدِ الكبير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوسّلُ بالإحسانِ إلى المحسن، ورعايةُ حقِّ الوالدِ الكبير."},"action":{"text":"توسّل إلى أهلِ الإحسانِ بإحسانهم في قضاءِ الحاجات، وراعِ حقَّ الوالدِ الكبيرِ وشفقتَه، فبرُّه من أعظمِ القرب."}},{"n":79,"reflection":{"text":"«قال معاذ الله أن نأخذ إلا من وجدنا متاعنا عنده إنا إذا لظالمون»: قال يوسف: أعوذ بالله أن نأخذ بريئًا مكانَ من وُجد المتاعُ عنده، فلا يؤخذ أحدٌ بجريرةِ غيره، إنا إن فعلنا ذلك لظالمون؛ ففي هذا عدلُ يوسفَ وامتناعُه عن الظلمِ ولو كان في ظاهرِ مصلحته؛ ففي هذا أنّ العدلَ ألّا يُؤخذ أحدٌ بذنبِ غيره، وأنّ الظلمَ حرامٌ ولو تراضى عليه الناس؛ فلا تأخذ بريئًا بجريرةِ غيره، ولا تظلم أحدًا ولو رضي، فالعدلُ واجبٌ لا يُتنازَل عنه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["معاذ الله"],"heart_state":{"text":"العدلُ بألّا يُؤخذ أحدٌ بذنبِ غيره، والحذرُ من الظلم."},"action":{"text":"لا تُحمّل أحدًا وزرَ غيره ولا تأخذه بجريرته، والزم العدلَ ولو خالف هواك أو مصلحتك الظاهرة، فالظلمُ حرام."}}]},{"title":"مناجاةُ الإخوة، ورجوعُهم إلى أبيهم","range":[80,82],"theme":"حياءُ الكبيرِ من الوفاءِ بالعهد، وصدقُهم في نقلِ ما علموا","verses":[{"n":80,"reflection":{"text":"«فلما استيأسوا منه خلصوا نجيا قال كبيرهم ألم تعلموا أن أباكم قد أخذ عليكم موثقا من الله ومن قبل ما فرطتم في يوسف فلن أبرح الأرض حتى يأذن لي أبي أو يحكم الله لي وهو خير الحاكمين»: فلما يئسوا من إطلاقِ أخيهم انفردوا يتناجون، فقال كبيرهم (روبيل): ألم تعلموا أنّ أباكم أخذ عليكم عهدًا مؤكّدًا بالله لتردّنّه، ومن قبلُ فرّطتم في يوسف؟ فبأيِّ وجهٍ نلقى أبانا؟ فلن أفارق أرضَ مصرَ حتى يأذن لي أبي بالرجوع أو يحكم الله لي بخلاصِ أخي، وهو خيرُ الحاكمين؛ ففي هذا حياءُ الكبيرِ من إخلافِ العهد، وتفويضُه لحكمِ الله؛ فاحفظ عهودك واستحيِ من إخلافها، وفوّض أمرك لله خيرِ الحاكمين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["خير الحاكمين"],"heart_state":{"text":"الوفاءُ بالعهدِ والحياءُ من إخلافه، وتفويضُ الأمرِ لله."},"action":{"text":"احفظ عهودك واستحيِ من إخلافها، وإذا أعياك أمرٌ ففوّضه لله خيرِ الحاكمين، فحكمُه خيرٌ وأعدل."}},{"n":81,"reflection":{"text":"«ارجعوا إلى أبيكم فقولوا يا أبانا إن ابنك سرق وما شهدنا إلا بما علمنا وما كنا للغيب حافظين»: قال كبيرهم لإخوته: ارجعوا إلى أبيكم فأخبروه: يا أبانا إنّ ابنك أُخذ بتهمةِ سرقةٍ ظهرت، وما شهدنا إلا بما رأينا وعلمنا (من إخراجِ الصواعِ من متاعه)، وما كنا نعلم الغيبَ حين عاهدناك أنه سيقع هذا؛ ففي هذا أنّ الإنسانَ لا يشهد إلا بما علم، ولا يُكلَّف بحفظِ ما لا يعلم من الغيب؛ فلا تشهد إلا بما علمت يقينًا، ولا تُحمّل نفسك ما لا تعلمه من العواقب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا يشهدَ المرءُ إلا بما علم، وألّا يُكلَّف بعلمِ الغيب."},"action":{"text":"لا تشهد إلا بما علمت يقينًا، ولا تُحمّل نفسك مسؤوليّةَ ما لا تعلمه من الغيبِ والعواقب، فذاك عذرٌ مقبول."}},{"n":82,"reflection":{"text":"«واسأل القرية التي كنا فيها والعير التي أقبلنا فيها وإنا لصادقون»: قالوا لأبيهم: واسأل أهلَ القريةِ (مصرَ) التي كنا فيها، والقافلةَ التي رجعنا معها، يخبروك بصدقنا فيما نقول، وإنا لصادقون فيما أخبرناك به؛ ففي هذا استشهادُهم بالبيّناتِ على صدقهم؛ ففي هذا أنّ الصادقَ يطمئن إلى التحقّقِ من خبره ولا يخشى السؤال؛ فكن صادقًا لا تخشى التثبّت من قولك، فالصادقُ لا يهاب التحقّق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الصادقَ لا يخشى التحقّقَ من خبره، فالصدقُ طمأنينة."},"action":{"text":"كن صادقًا في قولك حتى لا تخشى تحقّقَ الناسِ من خبرك، فالصادقُ يطمئن إلى بيّناته، والكاذبُ يهاب السؤال."}}]},{"title":"صبرُ يعقوبَ الجميل، وكظمُ حزنه","range":[83,84],"theme":"احتسابُ يعقوبَ ورجاؤه لقاءَ بنيه، وكظمُه للحزنِ العظيم","verses":[{"n":83,"reflection":{"text":"«قال بل سولت لكم أنفسكم أمرا فصبر جميل عسى الله أن يأتيني بهم جميعا إنه هو العليم الحكيم»: قال يعقوبُ لبنيه لمّا رجعوا بخبرِ بنيامين: بل زيّنت لكم أنفسكم أمرًا كما زيّنته من قبلُ في يوسف، فصبري صبرٌ جميلٌ لا شكوى فيه لغيرِ الله، عسى الله أن يأتيني بيوسفَ وأخيه وأخيهم الثالثِ جميعًا، إنه هو العليمُ بحالي الحكيمُ في تدبيره؛ ففي هذا رجاءُ يعقوبَ الواسعُ بالله مع طولِ البلاء، وصبرُه الجميل؛ فاصبر صبرًا جميلًا وأحسن الرجاءَ بالله ولو طال البلاء، فهو العليمُ الحكيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العليم","الحكيم","صبر جميل"],"heart_state":{"text":"الصبرُ الجميلُ مع سَعةِ الرجاءِ بالله ولو طال البلاء."},"action":{"text":"اصبر صبرًا جميلًا واملأ قلبك رجاءً بالله ولو طال بلاؤك، فقل «عسى الله أن يأتيني بهم»، فهو العليمُ الحكيم."}},{"n":84,"reflection":{"text":"«وتولى عنهم وقال يا أسفى على يوسف وابيضت عيناه من الحزن فهو كظيم»، وأعرض يعقوبُ عن بنيه من شدّةِ الحزنِ وتجدّدِ الأسى، وقال متأسّفًا: يا حزناه على يوسف! وابيضّت عيناه من كثرةِ البكاءِ والحزنِ حتى ضعف بصرُه، وهو ممتلئٌ حزنًا كاتمٌ له لا يبثّه للناس؛ ففي هذا أنّ الحزنَ على المصابِ جائزٌ إذا لم يصحبه تسخّطٌ أو شكوى للخلق، وأنّ كظمَ الحزنِ من الصبر؛ فاحزن إن شئت بلا تسخّط، واكظم حزنك عن الناسِ واشكه إلى الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"جوازُ الحزنِ بلا تسخّط، وكظمُه عن الناسِ وبثُّه لله."},"action":{"text":"احزن على مصابك بلا تسخّطٍ ولا شكوى للخلق، واكظم حزنك عن الناس، فالحزنُ رحمةٌ ما لم يصحبه اعتراضٌ على القدر."}}]},{"title":"شكوى يعقوبَ إلى الله، والنهيُ عن اليأس","range":[85,87],"theme":"أنّ الشكوى إلى الله لا تنافي الصبر، وأنّ اليأسَ من رَوحِ الله كفر","verses":[{"n":85,"reflection":{"text":"«قالوا تالله تفتأ تذكر يوسف حتى تكون حرضا أو تكون من الهالكين»: قال بنو يعقوبَ لأبيهم: والله لا تزال تذكر يوسفَ وتحزن عليه حتى تصير مريضًا مشرفًا على الهلاكِ أو تموت من الحزن؛ فعذلوه على دوامِ حزنه؛ ففي هذا أنّ المحبّةَ الصادقةَ تدوم، وأنّ حزنَ يعقوبَ كان لعظمِ محبّته؛ ففي هذا أنّ العبدَ قد يُلام على شيءٍ هو عبادةٌ عند الله؛ فلا يصدّك لومُ الناسِ عن حالٍ ترضاه لك ربّك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الانصياعِ للومِ الناسِ في حالٍ يرضاها الله."},"action":{"text":"لا يصدّك لومُ الناسِ عن حالٍ يحبّها الله منك، فربّ ملومٍ عند الخلقِ محمودٍ عند الله، فاجعل ميزانك رضاه."}},{"n":86,"reflection":{"text":"«قال إنما أشكو بثي وحزني إلى الله وأعلم من الله ما لا تعلمون»: قال يعقوب: إنما أشكو همّي الشديدَ وحزني إلى الله وحده لا إليكم ولا إلى غيره، وأعلم من رحمةِ الله ولطفِه وحسنِ صنعه ما لا تعلمون، فأرجو أن يجمعني بيوسف؛ ففي هذا أنّ الشكوى إلى الله وحده لا تنافي الصبر، بل هي عينُ العبوديّة، وأنّ حسنَ الظنِّ بالله عبادة؛ فاشكُ همّك إلى الله وحده، وأحسن ظنّك به، فذاك حالُ الصابرين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشكوى إلى الله وحده، وحسنُ الظنِّ به لا تنافيان الصبر."},"action":{"text":"اشكُ همّك وحزنك إلى الله وحده لا إلى الخلق، وأحسن ظنّك به، فالشكوى إليه عبادةٌ وعينُ الصبرِ لا نقيضُه."}},{"n":87,"reflection":{"text":"«يا بني اذهبوا فتحسسوا من يوسف وأخيه ولا تيأسوا من روح الله إنه لا ييأس من روح الله إلا القوم الكافرون»: قال يعقوبُ لبنيه: اذهبوا فابحثوا وتلمّسوا خبرَ يوسفَ وأخيه، ولا تقنطوا من فرجِ الله ورحمته، إنه لا ييأس من فرجِ الله ورحمته إلا القومُ الكافرون الجاحدون؛ ففي هذا أنّ الأملَ في فرجِ الله من الإيمان، وأنّ اليأسَ من صفاتِ الكفر؛ فلا تيأس من رحمةِ الله مهما اشتدّ الكرب، فاليأسُ من رَوحِ الله لا يجتمع مع الإيمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["روح الله"],"heart_state":{"text":"دوامُ الرجاءِ في فرجِ الله، والحذرُ من اليأسِ الذي ينافي الإيمان."},"action":{"text":"لا تيأس من فرجِ الله ورحمته مهما طال الكربُ واشتدّ، فالرجاءُ من الإيمان، واليأسُ من رَوحِ الله من صفاتِ الكافرين."}}]},{"title":"مجيءُ الإخوةِ محتاجين، وكشفُ يوسفَ عن نفسه","range":[88,90],"theme":"تذلّلُ الإخوةِ للحاجة، وأنّ التقوى والصبرَ سببُ التمكينِ والإحسان","verses":[{"n":88,"reflection":{"text":"«فلما دخلوا عليه قالوا يا أيها العزيز مسنا وأهلنا الضر وجئنا ببضاعة مزجاة فأوف لنا الكيل وتصدق علينا إن الله يجزي المتصدقين»: فلما دخل الإخوةُ على يوسفَ في المرّةِ الثالثةِ قالوا متذلّلين: يا أيها العزيزُ أصابنا وأهلَنا الجوعُ والشدّة، وجئنا ببضاعةٍ قليلةٍ رديئةٍ لا تفي، فأتمّ لنا الكيلَ وتصدّق علينا بالزيادةِ أو بالتجاوزِ عن رداءةِ بضاعتنا، إنّ الله يجزي المتصدّقين خيرَ الجزاء؛ ففي هذا أنّ الحاجةَ تُذلّ أهلَ الكِبر، وأنّ الترغيبَ في الصدقةِ ببيانِ جزائها؛ فأحسن إلى المحتاجين وتصدّق عليهم، فالله يجزي المتصدّقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ إلى المحتاجين والصدقةُ عليهم رجاءَ جزاءِ الله."},"action":{"text":"أحسن إلى المحتاجين وتصدّق عليهم بما تيسّر، فالله يجزي المتصدّقين خيرَ الجزاء، ولا تردّ سائلًا بحاجة."}},{"n":89,"reflection":{"text":"«قال هل علمتم ما فعلتم بيوسف وأخيه إذ أنتم جاهلون»: قال يوسفُ لهم (لمّا رقّ لحالهم وحان وقتُ الكشف): هل علمتم قبحَ ما فعلتم بيوسفَ (بإلقائه في الجبّ) وبأخيه (بالتفريقِ والأذى) حين كنتم جاهلين بعاقبةِ فعلكم؟ فعرّض لهم بنفسه ووبّخهم توبيخًا رفيقًا يفتح بابَ التوبة؛ ففي هذا أنّ التذكيرَ بالذنبِ لفتحِ بابِ التوبةِ من الحكمة؛ فذكّر المخطئَ بخطئه برفقٍ لتفتح له بابَ الرجوعِ لا لتعيّره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكيرُ بالخطأِ برفقٍ لفتحِ بابِ التوبةِ لا للتعيير."},"action":{"text":"إذا ذكّرت مخطئًا بخطئه فليكن برفقٍ يفتح له بابَ التوبةِ والرجوع، لا تعييرًا وتشفّيًا، فالمقصودُ الإصلاحُ لا الجرح."}},{"n":90,"reflection":{"text":"«قالوا أإنك لأنت يوسف قال أنا يوسف وهذا أخي قد من الله علينا إنه من يتق ويصبر فإن الله لا يضيع أجر المحسنين»: قالوا مندهشين: أإنك أنت يوسفُ حقًّا؟ قال: أنا يوسفُ وهذا أخي بنيامين، قد أنعم الله علينا بالجمعِ بعد الفرقةِ والعزِّ بعد الذلّ، إنه من يتّقِ الله ويصبر على البلاءِ فإنّ الله لا يضيع أجرَ المحسنين بل يجزيهم أحسنَ الجزاء؛ ففي هذا أنّ ثمرةَ التقوى والصبرِ التمكينُ وحسنُ العاقبة، وأنّ الله لا يضيع أجرَ المحسنين؛ فاتّق الله واصبر، فبهما تنال المنّةَ وحسنَ العاقبة، والله لا يضيع أجرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من يتق ويصبر","لا يضيع أجر المحسنين"],"heart_state":{"text":"أنّ التقوى والصبرَ سببُ المنّةِ وحسنِ العاقبة."},"action":{"text":"اتّق الله واصبر على البلاء، فبالتقوى والصبرِ ينال العبدُ منّةَ الله وحسنَ العاقبة، والله لا يضيع أجرَ المحسنين."}}]},{"title":"اعترافُ الإخوة، وعفوُ يوسفَ الكريم","range":[91,92],"theme":"إقرارُ الإخوةِ بفضلِ يوسفَ وخطئهم، وصفحُه الجميلُ عنهم","verses":[{"n":91,"reflection":{"text":"«قالوا تالله لقد آثرك الله علينا وإن كنا لخاطئين»: قال الإخوةُ معترفين: والله لقد فضّلك الله علينا بالعلمِ والحلمِ والملكِ والتقوى، وإن كنّا لمخطئين آثمين فيما فعلنا بك؛ فأقرّوا بفضله وبذنبهم؛ ففي هذا أنّ الاعترافَ بالفضلِ لأهله وبالخطأِ من شيمِ الكرام، وأنّ التواضعَ للحقِّ فضيلة؛ فاعترف بفضلِ ذي الفضل، وأقرّ بخطئك إذا أخطأت، فالاعترافُ بالحقِّ شجاعةٌ ونبل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعترافُ بالفضلِ لأهله، والإقرارُ بالخطأِ من شيمِ الكرام."},"action":{"text":"اعترف بفضلِ من فضّله الله عليك، وأقرّ بخطئك إذا أخطأت بلا مكابرة، فالاعترافُ بالحقِّ والفضلِ من النبلِ والشجاعة."}},{"n":92,"reflection":{"text":"«قال لا تثريب عليكم اليوم يغفر الله لكم وهو أرحم الراحمين»: قال يوسفُ لهم عند مقدرته عليهم: لا لومَ ولا تعنيفَ عليكم اليوم على ما فعلتم، يغفر الله لكم ذنبكم، وهو أرحمُ الراحمين بمن تاب؛ فعفا عنهم عفوًا كريمًا في موطنِ القدرةِ والانتقام؛ ففي هذا أنّ العفوَ عند المقدرةِ من أعظمِ الفضائل، وأنّ الكريمَ يصفح ويدعو لمن أساء إليه؛ فاعفُ عمّن ظلمك عند قدرتك عليه، وادعُ له بالمغفرة، فذاك خُلقُ الكرام.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أرحم الراحمين","لا تثريب"],"heart_state":{"text":"العفوُ عند المقدرة، والصفحُ الجميلُ عمّن أساء."},"action":{"text":"اعفُ عمّن أساء إليك عند قدرتك عليه، واصفح صفحًا جميلًا وادعُ له، فالعفوُ عند المقدرةِ من أشرفِ الأخلاق."}}]},{"title":"قميصُ يوسف، وإحساسُ يعقوبَ بريحه","range":[93,95],"theme":"سببُ عودةِ البصر، وصدقُ فراسةِ يعقوبَ رغمَ تكذيبِ الحاضرين","verses":[{"n":93,"reflection":{"text":"«اذهبوا بقميصي هذا فألقوه على وجه أبي يأت بصيرا وأتوني بأهلكم أجمعين»: قال يوسفُ لإخوته: خذوا قميصي هذا فألقوه على وجهِ أبي يعقوبَ يرجع بصيرًا بإذنِ الله بعد أن ابيضّت عيناه، وأتوني بأهلكم جميعًا لتقيموا عندي في مصر؛ ففي هذا أنّ الله يجعل الشفاءَ فيما يشاء من الأسباب، وأنّ كرمَ يوسفَ بلغ أن دعا الجميعَ إليه؛ ففي هذا أنّ الأسبابَ بيدِ الله يجعل فيها ما يشاء؛ فخذ بالأسبابِ واعلم أنّ الشفاءَ والفرجَ من الله وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأخذُ بالأسبابِ مع اليقينِ بأنّ الشفاءَ والفرجَ من الله."},"action":{"text":"خذ بالأسبابِ المشروعةِ للشفاءِ والفرج، واعلم أنّ الله يجعل النفعَ فيها بمشيئته، فالشافي هو الله وحده."}},{"n":94,"reflection":{"text":"«ولما فصلت العير قال أبوهم إني لأجد ريح يوسف لولا أن تفندون»، ولما خرجت القافلةُ من مصرَ متّجهةً إلى أبيهم، قال يعقوبُ لمن حوله: إني لأشمّ ريحَ يوسفَ (أوصله الله إليه بلطفه)، لولا أن تنسبوني إلى الخرفِ وضعفِ الرأي لصدّقتموني؛ ففي هذا كرامةٌ ليعقوبَ وصدقُ فراسته، وأنّ لطفَ الله يوصل البشرى لأوليائه؛ ففي هذا أنّ الله يُلطف بأوليائه بما يطمئن قلوبهم؛ فاطمئن إلى أنّ الله يبشّر أولياءه ويلطف بهم عند قربِ الفرج.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بلطفِ الله بأوليائه وبشراه لهم عند قربِ الفرج."},"action":{"text":"اطمئن إلى أنّ الله يلطف بأوليائه ويبشّرهم بقربِ الفرج، ولا يزعزع يقينك تكذيبُ من حولك إذا كنت على الحقّ."}},{"n":95,"reflection":{"text":"«قالوا تالله إنك لفي ضلالك القديم»: قال الحاضرون من أهله وولدِ ولده: والله إنك لفي خطئك القديمِ من فرطِ محبّتك ليوسفَ وذكرك له وتعلّقِ أملك برجوعه؛ فنسبوه إلى مجاوزةِ الصواب؛ ففي هذا أنّ صاحبَ الحقِّ قد يُتّهم في يقينه من الغافلين، وأنّ العبرةَ بما عند الله لا بظنِّ الناس؛ فلا يزعزع يقينك تخطئةُ الغافلين، فقد يكون الحقُّ معك وهم لا يشعرون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ثباتُ اليقينِ رغمَ تخطئةِ الغافلين، فالعبرةُ بالحقِّ لا بظنّهم."},"action":{"text":"اثبت على يقينك بالحقِّ ولو خطّأك الغافلون، فقد يكون الحقُّ معك وهم لا يدرون، والعبرةُ بما عند الله لا بظنِّ الناس."}}]},{"title":"عودةُ بصرِ يعقوب، واستغفارُ الإخوة","range":[96,98],"theme":"تحقّقُ فراسةِ يعقوب، وتوبةُ الإخوةِ وطلبُهم الاستغفار","verses":[{"n":96,"reflection":{"text":"«فلما أن جاء البشير ألقاه على وجهه فارتد بصيرا قال ألم أقل لكم إني أعلم من الله ما لا تعلمون»: فلما جاء المبشّرُ بنجاةِ يوسفَ وألقى القميصَ على وجهِ يعقوبَ رجع بصيرًا بإذنِ الله، فقال لبنيه: ألم أقل لكم إني أعلم من رحمةِ الله ولطفِه ما لا تعلمون؟ فتحقّق ما أخبر به؛ ففي هذا أنّ حسنَ الظنِّ بالله يُثمر، وأنّ فرجَ الله يأتي بعد طولِ الصبر؛ فأحسن ظنّك بالله وانتظر فرجه، فما خاب من أحسن الظنَّ بربّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ حسنَ الظنِّ بالله يُثمر الفرجَ بعد الصبر."},"action":{"text":"أحسن ظنّك بالله وانتظر فرجه ولو طال البلاء، فما خاب من أحسن ظنّه بربّه، وقد ردّ الله على يعقوبَ بصره وجمعَ شمله."}},{"n":97,"reflection":{"text":"«قالوا يا أبانا استغفر لنا ذنوبنا إنا كنا خاطئين»: قال بنو يعقوبَ لأبيهم نادمين: يا أبانا اطلب لنا من الله المغفرةَ لذنوبنا، إنا كنّا مخطئين آثمين فيما فعلنا بك وبأخينا؛ فبادروا إلى التوبةِ وطلبِ الاستغفار؛ ففي هذا أنّ الاعترافَ بالذنبِ وطلبَ المغفرةِ بابُ التوبة، وأنّ التوسّلَ بدعاءِ الصالحينَ مشروع؛ فبادر بالتوبةِ والاعترافِ بذنبك، واطلب دعاءَ الصالحين لك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ إلى التوبةِ والاعترافِ بالذنبِ وطلبِ الاستغفار."},"action":{"text":"إذا أذنبت فبادر بالتوبةِ والاعترافِ بذنبك، واطلب المغفرةَ من الله، ولا بأس بطلبِ دعاءِ الصالحين لك."}},{"n":98,"reflection":{"text":"«قال سوف أستغفر لكم ربي إنه هو الغفور الرحيم»: قال يعقوب: سوف أطلب لكم المغفرةَ من ربّي (أخّرها إلى وقتِ الإجابةِ كالسحرِ، أو رفقًا)، إنه هو الغفورُ الواسعُ المغفرةِ الرحيمُ بعباده؛ ففي هذا حلمُ يعقوبَ وعفوُه، ورجاؤه سَعةَ مغفرةِ الله؛ ففي هذا أنّ العفوَ عن المسيءِ والدعاءَ له من شيمِ الكرام، وأنّ الله غفورٌ رحيم؛ فاعفُ عمّن أساء إليك وادعُ له، وأبشر بأنّ الله غفورٌ رحيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"العفوُ عن المسيءِ والدعاءُ له، والرجاءُ في مغفرةِ الله."},"action":{"text":"اعفُ عمّن أساء إليك وادعُ له بالمغفرة، وأبشر بسَعةِ مغفرةِ الله ورحمته، فهو الغفورُ الرحيمُ لمن تاب وأناب."}}]},{"title":"دخولُ مصرَ وتأويلُ الرؤيا","range":[99,101],"theme":"تحقّقُ رؤيا يوسف، ولطفُ الله في تدبيره، ودعاءُ يوسفَ بالوفاةِ على الإسلام","verses":[{"n":99,"reflection":{"text":"«فلما دخلوا على يوسف آوى إليه أبويه وقال ادخلوا مصر إن شاء الله آمنين»: فلما قدم يعقوبُ وأهلُه ودخلوا على يوسفَ في مصر، ضمّ إليه أباه وأمّه (أو خالته) وأكرمهما، وقال للجميع: ادخلوا مصرَ إن شاء الله آمنين من الخوفِ والجوعِ والحاجة؛ ففي هذا برُّ يوسفَ بوالديه وإكرامُه لهما، وتعليقُ الأمورِ بمشيئةِ الله؛ فبرَّ والديك وأكرمهما، وعلّق أمورك بمشيئةِ الله في كلِّ ما تعزم عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"برُّ الوالدينِ وإكرامُهما، وتعليقُ الأمورِ بمشيئةِ الله."},"action":{"text":"برَّ والديك وأكرمهما غايةَ الإكرام، وعلّق عزائمك بمشيئةِ الله فقل «إن شاء الله»، كما فعل يوسفُ الصدّيق."}},{"n":100,"reflection":{"text":"«ورفع أبويه على العرش وخروا له سجدا وقال يا أبت هذا تأويل رؤياي من قبل قد جعلها ربي حقا وقد أحسن بي إذ أخرجني من السجن وجاء بكم من البدو من بعد أن نزغ الشيطان بيني وبين إخوتي إن ربي لطيف لما يشاء إنه هو العليم الحكيم»، ورفع يوسفُ أبويه على سريرِ ملكه تكريمًا، وخرّ له أبواه وإخوته سجودَ تحيّةٍ وتعظيمٍ (كان جائزًا في شرعهم)، وقال: يا أبتِ هذا تفسيرُ رؤياي التي رأيتها من قبل (الكواكبُ والشمسُ والقمرُ ساجدين)، قد جعلها ربّي حقًّا واقعًا، وقد أحسن إليّ إذ أخرجني من السجن وجاء بكم من الباديةِ بعد أن أفسد الشيطانُ بيني وبين إخوتي؛ إنّ ربّي لطيفٌ يدبّر ما يشاء بلطفٍ وحكمة، إنه هو العليمُ الحكيم؛ ففي هذا تحقّقُ وعدِ الله، ونسبةُ يوسفَ الإحسانَ لله، وأدبُه إذ لم يذكر جبَّ الإخوةِ ونسب النزغَ للشيطان؛ فانسب الفضلَ لله، واستر إساءةَ من أساء إليك، واعلم أنّ ربّك لطيفٌ بأوليائه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["اللطيف","العليم","الحكيم"],"heart_state":{"text":"نسبةُ الفضلِ لله، والأدبُ في سترِ إساءةِ المسيء، واليقينُ بلطفِ الله."},"action":{"text":"انسب الفضلَ والإحسانَ إلى الله، واستر إساءةَ من أساء إليك ولا تفضحه، واطمئن إلى أنّ ربّك لطيفٌ يدبّر أمرك بحكمة."}},{"n":101,"reflection":{"text":"«رب قد آتيتني من الملك وعلمتني من تأويل الأحاديث فاطر السماوات والأرض أنت وليي في الدنيا والآخرة توفني مسلما وألحقني بالصالحين»: قال يوسفُ داعيًا شاكرًا في تمامِ نعمته: ربِّ قد أعطيتني من الملكِ والسلطان، وعلّمتني تعبيرَ الرؤى، يا خالقَ السماواتِ والأرضِ ومبدعَهما، أنت متولّي أمري وناصري في الدنيا والآخرة، توفّني على الإسلامِ حين تتوفّاني، وألحقني بعبادك الصالحين في الجنّة؛ ففي هذا أنّ العبدَ في أوجِ النعمةِ يتذلّل لله ويسأله حسنَ الخاتمة، وأنّ أعظمَ المطالبِ الموتُ على الإسلام؛ فاسأل الله في نعمك حسنَ الخاتمةِ والوفاةَ على الإسلام، فذاك غايةُ المطلب.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فاطر السماوات والأرض","الولي"],"heart_state":{"text":"سؤالُ حسنِ الخاتمةِ والوفاةِ على الإسلامِ في أوجِ النعمة."},"action":{"text":"اسأل الله دائمًا حسنَ الخاتمةِ والوفاةَ على الإسلامِ والإلحاقَ بالصالحين، فذاك أعظمُ المطالب، وتذلّل له في نعمك."}}]},{"title":"عبرةُ القصّة، وإعراضُ الأكثرين","range":[102,104],"theme":"أنّ القصّةَ من أنباءِ الغيب، وأنّ أكثرَ الناسِ لا يؤمنون رغم البلاغ","verses":[{"n":102,"reflection":{"text":"«ذلك من أنباء الغيب نوحيه إليك وما كنت لديهم إذ أجمعوا أمرهم وهم يمكرون»: تلك القصّةُ من أخبارِ الغيبِ التي نوحيها إليك يا محمد، وما كنت حاضرًا مع إخوةِ يوسفَ حين عزموا على كيدهم ودبّروا مكرهم، فإخبارُك بها دليلُ نبوّتك؛ ففي هذا أنّ إخبارَ النبيِّ بالغيبِ برهانُ صدقه؛ فأيقن بصدقِ القرآنِ ونبوّةِ محمدٍ ﷺ، فإخبارُه بالمغيّباتِ دليلُ أنه وحيٌ من الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بصدقِ الوحيِ ونبوّةِ محمدٍ ﷺ ببرهانِ الغيب."},"action":{"text":"أيقن بصدقِ القرآنِ ونبوّةِ محمدٍ ﷺ، فإخبارُه بأنباءِ الغيبِ التي لم يشهدها دليلٌ قاطعٌ أنه وحيٌ من الله."}},{"n":103,"reflection":{"text":"«وما أكثر الناس ولو حرصت بمؤمنين»، وما أكثرُ الناسِ بمؤمنين ولو حرصت غايةَ الحرصِ على هدايتهم، فأكثرهم معرضون؛ ففي هذا تسليةٌ للنبيِّ بألّا يحزن على إعراضهم، وأنّ الهدايةَ بيدِ الله؛ فابذل الدعوةَ ولا تحزن على من أعرض، فالهدايةُ بيدِ الله لا بحرصك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ الدعوةِ بلا حزنٍ على إعراضِ الأكثرين."},"action":{"text":"ابذل الدعوةَ إلى الحقِّ بحرصٍ وإخلاص، ولا تحزن على من أعرض، فالهدايةُ بيدِ الله، وليس عليك إلا البلاغ."}},{"n":104,"reflection":{"text":"«وما تسألهم عليه من أجر إن هو إلا ذكر للعالمين»، وما تطلب منهم يا محمد على تبليغِ القرآنِ والدعوةِ أجرًا فيثقل عليهم، ما هذا القرآنُ إلا عظةٌ وتذكرةٌ للناسِ أجمعين إنسِهم وجنّهم؛ ففي هذا أنّ تجرّدَ الداعيةِ عن الأجرِ يقيم الحجّة، وأنّ القرآنَ ذكرى للعالمين؛ فادعُ إلى الله بلا مقابل، واجعل القرآنَ ذكرى تنتفع بها وتُذكّر بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ في الدعوةِ بلا مقابل، والانتفاعُ بالقرآنِ ذكرى."},"action":{"text":"ادعُ إلى الحقِّ محتسبًا بلا طلبِ أجرٍ من الناس، واجعل القرآنَ ذكرى لك ولغيرك، فهو ذكرٌ للعالمين أجمعين."}}]},{"title":"آياتُ الله المُعرَضُ عنها، وخطرُ الغفلة","range":[105,107],"theme":"غفلةُ الناسِ عن آياتِ الله، وشوبُ إيمانِ الأكثرين بالشرك، والحذرُ من البغتة","verses":[{"n":105,"reflection":{"text":"«وكأين من آية في السماوات والأرض يمرون عليها وهم عنها معرضون»، وكم من علامةٍ ودليلٍ على وحدانيّةِ الله وقدرته في السماواتِ والأرضِ يمرّ عليها الناسُ ويشاهدونها وهم عنها معرضون لا يتفكّرون ولا يعتبرون؛ ففي هذا أنّ الغفلةَ تحجب عن الاعتبارِ بالآيات؛ فتفكّر في آياتِ الله في الكون، ولا تكن من الغافلين المعرضين الذين يمرّون عليها بلا اعتبار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في آياتِ الله، والحذرُ من الغفلةِ والإعراضِ عنها."},"action":{"text":"تفكّر في آياتِ الله في السماواتِ والأرض، ولا تمرّ عليها غافلًا معرضًا، فالاعتبارُ بها بابُ الإيمانِ واليقين."}},{"n":106,"reflection":{"text":"«وما يؤمن أكثرهم بالله إلا وهم مشركون»، وما يؤمن أكثرُ الناسِ بالله (بأنه الخالقُ الرازق) إلا وهم مشركون به في العبادةِ (يعبدون معه غيره) أو في الرياءِ أو الطاعةِ لغيره؛ ففي هذا أنّ الإقرارَ بالربوبيّةِ لا يكفي دون إفرادِ الله بالعبادة، وأنّ الشركَ قد يخفى؛ فأخلص توحيدك لله في العبادةِ والقصد، واحذر الشركَ الخفيَّ كالرياء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ التوحيدِ في العبادةِ والقصد، والحذرُ من الشركِ الخفيّ."},"action":{"text":"أخلص عبادتك وقصدك لله وحده، ولا يكفِ الإقرارُ بأنه الخالق، واحذر الشركَ الخفيَّ كالرياءِ وطاعةِ الهوى."}},{"n":107,"reflection":{"text":"«أفأمنوا أن تأتيهم غاشية من عذاب الله أو تأتيهم الساعة بغتة وهم لا يشعرون»: أفأمِن هؤلاء المعرضون أن يأتيهم عذابٌ يعمّهم ويغشاهم من عذابِ الله، أو تأتيهم القيامةُ فجأةً وهم غافلون لا يشعرون بها؟ ففي هذا تخويفٌ من بغتةِ العذابِ والساعة، وحثٌّ على اليقظةِ والاستعداد؛ فلا تأمن بغتةَ العذابِ والموت، وكن مستعدًّا بالعملِ الصالحِ في كلِّ حين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من بغتةِ العذابِ والساعة، والاستعدادُ الدائم."},"action":{"text":"لا تأمن أن يأتيك عذابُ الله أو الموتُ أو الساعةُ بغتةً وأنت غافل، فكن مستعدًّا دائمًا بالتوبةِ والعملِ الصالح."}}]},{"title":"سبيلُ الدعوةِ على بصيرة، وسنّةُ الرسل","range":[108,109],"theme":"أنّ الدعوةَ إلى الله على علمٍ وبصيرة، وأنّ الرسلَ بشرٌ والعاقبةَ للمتقين","verses":[{"n":108,"reflection":{"text":"«قل هذه سبيلي أدعو إلى الله على بصيرة أنا ومن اتبعني وسبحان الله وما أنا من المشركين»: قل يا محمد: هذه طريقتي وسنّتي، أدعو إلى عبادةِ الله وحده على علمٍ ويقينٍ وحجّةٍ واضحة، أنا ومن اتّبعني من المؤمنين نسير على هذه البصيرة، وأنزّه الله عن كلِّ شريك، ولست من المشركين؛ ففي هذا أنّ الدعوةَ إلى الله يجب أن تكون على علمٍ وبصيرة، وأنها سبيلُ النبيِّ وأتباعه؛ فادعُ إلى الله على بصيرةٍ وعلم، ونزّه الله عن الشرك، وسر على سبيلِ النبيِّ ﷺ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["على بصيرة","سبحان الله"],"heart_state":{"text":"الدعوةُ إلى الله على علمٍ وبصيرة، والسيرُ على سبيلِ النبيِّ ﷺ."},"action":{"text":"ادعُ إلى الله على علمٍ وبصيرةٍ لا على جهل، وسر على سبيلِ النبيِّ ﷺ وأتباعه، ونزّه الله عن كلِّ شريك."}},{"n":109,"reflection":{"text":"«وما أرسلنا من قبلك إلا رجالا نوحي إليهم من أهل القرى أفلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم ولدار الآخرة خير للذين اتقوا أفلا تعقلون»، وما أرسلنا من قبلك يا محمد إلا رجالًا من البشرِ نوحي إليهم، من أهلِ المدنِ والقرى (لا من البادية)، فلا غرابةَ في بشريّةِ الرسل؛ أفلم يسر المكذّبون في الأرضِ فينظروا كيف كان عاقبةُ المكذّبين قبلهم من الهلاك؟ ولدارُ الآخرةِ خيرٌ للذين اتّقوا الله من الدنيا وزينتها، أفلا تعقلون فتؤثروا الباقيةَ على الفانية؟ ففي هذا أنّ الرسلَ بشرٌ، وأنّ الاعتبارَ بالتاريخِ من العقل، وأنّ الآخرةَ خيرٌ للمتقين؛ فاعتبر بمصارعِ المكذّبين، وآثر الآخرةَ الباقيةَ على الدنيا الفانية.","source":"تفسير السعدي","grade":"ma'thur"},"names":["دار الآخرة خير"],"heart_state":{"text":"الاعتبارُ بعاقبةِ المكذّبين، وإيثارُ الآخرةِ الباقيةِ للمتقين."},"action":{"text":"اعتبر بعاقبةِ الأممِ المكذّبةِ في التاريخ، وآثر الدارَ الآخرةَ الباقيةَ على الدنيا الفانية، فهي خيرٌ للمتقين."}}]},{"title":"نصرُ الله عند اشتدادِ الكرب، وعبرةُ القصص","range":[110,111],"theme":"أنّ النصرَ يأتي عند غايةِ الشدّة، وأنّ في قصصِ الأنبياءِ عبرةً وهدًى","verses":[{"n":110,"reflection":{"text":"«حتى إذا استيأس الرسل وظنوا أنهم قد كذبوا جاءهم نصرنا فنجي من نشاء ولا يرد بأسنا عن القوم المجرمين»: حتى إذا بلغ الأمرُ بالرسلِ غايةَ الشدّةِ فاستيأسوا من إيمانِ قومهم، وظنّ المكذّبون أنّ الرسلَ قد كُذّبوا فيما وُعدوا من النصر (أو ظنّ الرسلُ أنّ أتباعهم كذّبوهم)، جاءهم نصرُنا عند تلك الغاية، فنُنجّي من نشاء من الرسلِ والمؤمنين، ولا يُدفع عذابُنا عن القومِ المجرمين؛ ففي هذا أنّ نصرَ الله يأتي عند اشتدادِ الكربِ وبلوغِ الغاية، فلا يُستبطأ؛ فاصبر عند اشتدادِ الكرب، فنصرُ الله قريبٌ يأتي عند غايةِ الشدّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ عند اشتدادِ الكرب، فنصرُ الله يأتي عند غايةِ الشدّة."},"action":{"text":"اصبر عند اشتدادِ الكربِ وضيقِ الأمل، فنصرُ الله يأتي عند غايةِ الشدّة، فلا تستبطئه ولا تيأس من رَوحه."}},{"n":111,"reflection":{"text":"«لقد كان في قصصهم عبرة لأولي الألباب ما كان حديثا يفترى ولكن تصديق الذي بين يديه وتفصيل كل شيء وهدى ورحمة لقوم يؤمنون»: لقد كان في قصصِ الأنبياءِ وأممهم (ومنها قصّةُ يوسف) عبرةٌ وعظةٌ لأصحابِ العقولِ الراجحة؛ ما كان هذا القرآنُ حديثًا مختلقًا يُفترى، ولكنه مصدّقٌ لما قبله من الكتب، ومفصّلٌ لكلِّ ما يحتاجه العبادُ من الأحكامِ والأخبار، وهدًى من الضلالِ ورحمةٌ لقومٍ يؤمنون به ويعملون؛ فخُتمت السورةُ ببيانِ أنّ القصصَ عبرةٌ وأنّ القرآنَ هدًى ورحمة؛ فاطلب العبرةَ من قصصِ القرآنِ بعقلك، واجعله هُداك ورحمتك، فهو تصديقٌ وتفصيلٌ وهدًى ورحمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["عبرة لأولي الألباب","هدى","رحمة"],"heart_state":{"text":"طلبُ العبرةِ من قصصِ القرآنِ بالعقل، واتّخاذُه هدًى ورحمة."},"action":{"text":"تدبّر قصصَ القرآنِ بعقلك واطلب فيها العبرة، واجعل القرآنَ هُداك ورحمتك، فهو تصديقٌ لما قبله وتفصيلٌ وهدًى ورحمةٌ للمؤمنين."}}]}],"coverage":{"covered":111,"total":111}};
